-- ===== client-balance-local.sql =====
-- LOCAL PRO ONLY. Round 1 after the manual walkthrough (2026-11-12): ONE customer balance.
-- The walkthrough showed three different balances for the same customer (customer record
-- ₡708.550, statement ₡658.550, invoice draft ₡1.008.550). The single formula, per job:
--
--   agreed      = latest manual agreement entry (owner edit) ▸ else the accepted request quote
--                 (request-quotes-local.sql) ▸ else the accepted private estimate continued
--                 into the job (pro_private_estimate_work_agreements, CRC)
--   paid        = Σ ledger payments − Σ ledger payment voids (pro_client_entries). A retainer
--                 (anticipo) received is ALWAYS one ledger payment, and applying it to an
--                 invoice only allocates that same money: it is counted once, here.
--   credit notes= Σ credit-note applications of the job not reverted (pro_credit_applications)
--   customer balance = max(agreed − paid − credit notes, 0)       (null while agreed is null)
--   creditCents (money in favour) = max(paid − agreed, 0)         (a credit note never is money)
--
-- Used by: customer record (pro_client_operations_page summary.customerBalanceCents),
-- customer statement (pro_client_statement_page: Σ max(max(agreed−paid,0) − notes,0), the same
-- number), and the invoice draft ("saldo actual del cliente en este trabajo", read live through
-- pro_client_job_balance). balanceCents (agreed − paid) is kept unchanged for the payment
-- validations that already rely on it. Read-only module: no table and no row is changed.
-- Supersedes pro_work_account (request-quotes-local.sql) and pro_client_operations_page
-- (client-operations-draft.sql) with the same signatures and only ADDED keys.
begin;
create or replace function public.pro_client_job_credit_notes(p_user uuid,p_work text) returns bigint
language sql stable security invoker set search_path=public,pg_temp as $$
 select coalesce(sum(a.amount_cents),0)::bigint from public.pro_credit_applications a join public.pro_credits c on c.owner_id=a.owner_id and c.id=a.credit_id
 where a.owner_id=p_user and a.work_id=p_work and c.kind='credit_note' and a.invoice_application_id is null
  and not exists(select 1 from public.pro_credit_application_reversals r where r.owner_id=a.owner_id and r.application_id=a.id) $$;
create or replace function public.pro_work_account(p_user uuid,p_work text) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 with account_values as (
 select w.*,
 coalesce(
  (select amount_cents from pro_client_entries where user_id=p_user and work_id=w.id and kind='agreement' order by position desc limit 1),
  -- Quotes are CRC documents with integer-colon totals. Derive cents exactly;
  -- this is a reading of the accepted document, never a charge or ledger entry.
  (select q.total::bigint*100
   from pro_request_quotes m
   join pro_appointment_requests r on r.id=m.request_id and r.owner_id=m.owner_id and r.client_user_id=m.client_user_id
   join quotes q on q.id=m.quote_id and q.client_id=m.client_user_id and q.professional_id=r.professional_id
   join professionals p on p.id=q.professional_id and p.profile_id=m.owner_id
   where m.owner_id=p_user and m.accepted and q.status='accepted' and q.deleted_at is null
    and r.work_id=w.id and w."externalQuoteId"=q.id::text and nullif(w."quoteId",'') is null
    and w."clientId"='reservation-'||r.client_user_id::text and w."bookingClientId"=r.client_user_id::text),
  -- Round 1: the accepted private estimate continued into this job (CRC only), until the owner edits it.
  (select g.total_cents from pro_private_estimate_work_agreements g where g.owner_id=p_user and g.work_id=w.id and g.currency='CRC')
 ) as agreed,
 case when exists(select 1 from pro_client_entries where user_id=p_user and work_id=w.id and kind='agreement') then 'agreement'
  when exists(select 1 from pro_private_estimate_work_agreements g where g.owner_id=p_user and g.work_id=w.id and g.currency='CRC')
   and not exists(select 1 from pro_request_quotes m join pro_appointment_requests r on r.id=m.request_id where m.owner_id=p_user and m.accepted and r.work_id=w.id and w."externalQuoteId" is not null) then 'estimate'
  else null end as agreed_kind,
 (select (v.content->>'taxCents')::bigint from pro_private_estimate_work_agreements g join pro_private_estimate_publications v on v.id=g.publication_id where g.owner_id=p_user and g.work_id=w.id and g.currency='CRC') as estimate_tax,
 public.pro_client_job_credit_notes(p_user,w.id) as credit_notes,
 (select coalesce(sum(case when kind='payment' then amount_cents when kind='payment_void' then -amount_cents else 0 end),0) from pro_client_entries where user_id=p_user and work_id=w.id) as paid,
 (select count(*) from pro_client_entries e where e.user_id=p_user and e.work_id=w.id and e.kind='material' and not exists(select 1 from pro_client_entries r where r.user_id=e.user_id and r.reversal_id=e.id)) as materials,
 (select coalesce(sum(case when kind='material' then round(quantity*unit_cost,2) when kind='material_return' then -round(quantity*unit_cost,2) else 0 end),0) from pro_client_entries where user_id=p_user and work_id=w.id) as material_cost
 from pro_work w where w.user_id=p_user and w.id=p_work
 ) select jsonb_build_object('id',id,'service',service,'stage',stage,'cancelled',cancelled,'start',start,'quoteId',"quoteId",'externalQuoteId',"externalQuoteId",'agreedCents',agreed,'paidCents',paid,'balanceCents',coalesce(agreed,0)-paid,'materialCount',materials,'materialCost',material_cost,
 'agreedSource',case when agreed is null then null when agreed_kind is not null then agreed_kind else 'quote' end,
 'agreedTaxCents',case when agreed_kind='estimate' then estimate_tax else null end,
 'creditNotesCents',credit_notes,
 'customerBalanceCents',case when agreed is null then null else greatest(agreed-paid-credit_notes,0) end) from account_values;
$$;

create or replace function public.pro_client_operations_page(p_user uuid,p_client text,p_work text default '',p_after jsonb default null,p_entries_after jsonb default null) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 with accounts as materialized (
 select pro_work_account(p_user,w.id) as a,coalesce(to_char(pro_instant(w.start) at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'') as at from pro_work w where w.user_id=p_user and w."clientId"=p_client
 ), page as (
 select a,at from accounts where p_after is null or at<p_after->>'at' or at=p_after->>'at' and a->>'id'>p_after->>'id' order by at desc,a->>'id' limit 21
 ), entries as (
 select e.*,exists(select 1 from pro_client_entries r where r.user_id=e.user_id and r.reversal_id=e.id) as reversed
 from pro_client_entries e where e.user_id=p_user and e.client_id=p_client and e.work_id=p_work and (p_entries_after is null or e.position<(p_entries_after->>'position')::bigint) order by e.position desc limit 21
 ) select jsonb_build_object(
 'revision',(select revision from pro_workspace_core where user_id=p_user),
 'summary',jsonb_build_object('agreedCents',coalesce((select sum((a->>'agreedCents')::bigint) from accounts),0),'paidCents',coalesce((select sum((a->>'paidCents')::bigint) from accounts),0),'balanceCents',coalesce((select sum((a->>'balanceCents')::bigint) from accounts),0),
 'creditNotesCents',coalesce((select sum((a->>'creditNotesCents')::bigint) from accounts),0),'customerBalanceCents',coalesce((select sum((a->>'customerBalanceCents')::bigint) from accounts),0),'unpriced',(select count(*) from accounts where a->>'agreedCents' is null and not(a->>'cancelled')::boolean)),
 'items',coalesce((select jsonb_agg(a order by at desc,a->>'id') from (select a,at from page order by at desc,a->>'id' limit 20) p),'[]'),
 'nextCursor',case when (select count(*) from page)>20 then (select jsonb_build_object('at',at,'id',a->>'id') from page order by at desc,a->>'id' offset 19 limit 1) else null end,
 'work',(select a from accounts where a->>'id'=p_work),
 'entries',coalesce((select jsonb_agg(jsonb_build_object('id',id,'kind',kind,'amountCents',amount_cents,'quantity',quantity,'label',label,'at',created_at,'reversed',reversed) order by position desc) from (select * from entries order by position desc limit 20) p),'[]'),
 'nextEntryCursor',case when (select count(*) from entries)>20 then (select jsonb_build_object('position',position::text) from entries order by position desc offset 19 limit 1) else null end
 ) where exists(select 1 from pro_clients where user_id=p_user and id=p_client) and (p_work='' or exists(select 1 from pro_work where user_id=p_user and "clientId"=p_client and id=p_work));
$$;

create or replace function public.pro_client_job_balance(p_user uuid,p_work text) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare a jsonb;
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_user),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if p_work is null or length(p_work) not between 1 and 160 then raise exception 'Invalid job' using errcode='22023';end if;
 a:=public.pro_work_account(p_user,p_work);if a is null then return null;end if;
 return jsonb_build_object('workId',p_work,'agreedCents',a->'agreedCents','agreedSource',a->'agreedSource','paidCents',a->'paidCents','creditNotesCents',a->'creditNotesCents',
  'customerBalanceCents',a->'customerBalanceCents','creditCents',greatest(-(a->>'balanceCents')::bigint,0));
end $$;
revoke all on function public.pro_client_job_credit_notes(uuid,text),public.pro_work_account(uuid,text),public.pro_client_operations_page(uuid,text,text,jsonb,jsonb),public.pro_client_job_balance(uuid,text) from public,anon,authenticated;
grant execute on function public.pro_client_job_credit_notes(uuid,text),public.pro_work_account(uuid,text),public.pro_client_operations_page(uuid,text,text,jsonb,jsonb),public.pro_client_job_balance(uuid,text) to service_role;
notify pgrst,'reload schema';
commit;

-- ===== work-header-local.sql =====
-- LOCAL PRO ONLY. Round 1 after the manual walkthrough (2026-11-12): job header and agenda list.
-- The walkthrough job still said «Nuevo · Sin programar» with a plan (12–28 nov), an accepted
-- estimate and a contract, and did not appear under «Pendientes». Read-only: no table is created
-- and no job, plan, estimate or contract row is changed. One derived phase per job:
--
--   cancelled / completed          the job's own state
--   in_progress                    today (America/Costa_Rica) inside the job dates or the plan range
--   scheduled                      the job has dates, or a plan, that start later
--   contracted                     a contract of the job was accepted by the customer
--   estimate_accepted              an accepted estimate was continued into the job
--   contract_sent                  a contract was shared and is waiting for the customer
--   quoting / new                  the job's own stage otherwise
--
-- Plan range = min(planned_start) … max(planned_end) of the job's not archived tasks.
-- Agenda list («Citas y trabajos»): the owner's jobs are 'pending' while their phase is new,
-- quoting, estimate_accepted, contract_sent or contracted without dates or plan; 'confirmed' once
-- scheduled/in progress. Supersedes pro_appointment_inbox (appointment-list-local.sql).
begin;
create or replace function public.pro_work_header_facts(p_owner uuid,p_work text) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 with w as(select * from public.pro_work where user_id=p_owner and id=p_work),
 plan as(select min(p.planned_start) s,max(p.planned_end) e from public.pro_work_schedule_plans p join public.pro_work_tasks t on t.owner_id=p.owner_id and t.work_id=p.work_id and t.id=p.task_id
   where p.owner_id=p_owner and p.work_id=p_work and not t.archived and p.planned_start is not null),
 contract as(select c.status from public.pro_contracts c where c.owner_id=p_owner and c.work_id=p_work and c.status<>'voided'
   order by case c.status when 'accepted' then 0 when 'shared' then 1 when 'draft' then 2 else 3 end,c.number desc limit 1),
 facts as(select w.*,(select s from plan) plan_start,(select e from plan) plan_end,(select status from contract) contract_status,
   exists(select 1 from public.pro_private_estimate_work_agreements g where g.owner_id=p_owner and g.work_id=p_work) estimate_accepted,
   -- Round 7A: a quote of this job accepted by the customer but not yet continued into it (code path).
   exists(select 1 from public.pro_private_estimates d join public.pro_private_estimate_publications v on v.owner_id=d.owner_id and v.estimate_id=d.id
     join public.pro_private_estimate_publication_states s on s.publication_id=v.id
     where d.owner_id=p_owner and d.source->>'kind'='work' and d.source->>'id'=p_work and s.status='accepted'
      and not exists(select 1 from public.pro_private_estimate_work_agreements g where g.owner_id=p_owner and g.publication_id=v.id)) estimate_awaiting,
   (now() at time zone 'America/Costa_Rica')::date today,
   case when btrim(w.start)='' then null else (public.pro_instant(w.start) at time zone 'America/Costa_Rica')::date end job_start,
   case when btrim(w."end")='' then null else (public.pro_instant(w."end") at time zone 'America/Costa_Rica')::date end job_end
   from w)
 select jsonb_build_object('workId',f.id,'stage',f.stage,'cancelled',coalesce(f.cancelled,false),
  'planStart',to_char(f.plan_start,'YYYY-MM-DD'),'planEnd',to_char(f.plan_end,'YYYY-MM-DD'),'contractStatus',f.contract_status,'estimateAccepted',f.estimate_accepted,'estimateAwaitingContinue',f.estimate_awaiting and not f.estimate_accepted,
  'phase',case when coalesce(f.cancelled,false) then 'cancelled' when f.stage='completed' then 'completed'
   when f.job_start is not null and f.today between f.job_start and coalesce(f.job_end,f.job_start) or f.plan_start is not null and f.today between f.plan_start and f.plan_end then 'in_progress'
   when f.job_start is not null and f.job_start>f.today or f.plan_start is not null and f.plan_start>f.today then 'scheduled'
   when f.contract_status='accepted' then 'contracted'
   when f.estimate_accepted then 'estimate_accepted'
   when f.contract_status='shared' then 'contract_sent'
   when f.stage='quoting' then 'quoting' when f.stage='scheduled' then 'scheduled' else 'new' end)
 from facts f $$;
create or replace function public.pro_work_header(p_actor uuid,p_work text) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if p_work is null or length(p_work) not between 1 and 160 then raise exception 'Invalid job' using errcode='22023';end if;
 return public.pro_work_header_facts(p_actor,p_work);
end $$;
create or replace function public.pro_appointment_inbox(p_owner uuid,p_status text default 'pending',p_after jsonb default null) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 with entries as (
 select r.id::text id,'request'::text source,r.client_name client,r.service,
 coalesce(pro_instant(w.start),r.proposed_start,r.requested_start) start,
 coalesce(pro_instant(w.start),r.proposed_start,r.requested_start,r.created_at) at,
 case when w.cancelled or r.status in ('cancelled','declined') then 'cancelled' when w.stage='completed' or r.status='completed' then 'completed' when r.status in ('requested','proposed') then 'pending' else 'confirmed' end status,
 r.status detail_status
 from pro_appointment_requests r left join pro_work w on w.user_id=r.owner_id and w.id=r.work_id where r.owner_id=p_owner and r.origin='booking'
 union all
 select w.id,'manual',w.client,w.service,coalesce(pro_instant(nullif(w.start,'')),(h.facts->>'planStart')::date::timestamp at time zone 'America/Costa_Rica'),
 coalesce(pro_instant(nullif(w.start,'')),(h.facts->>'planStart')::date::timestamp at time zone 'America/Costa_Rica','epoch'::timestamptz),
 case h.facts->>'phase' when 'cancelled' then 'cancelled' when 'completed' then 'completed' when 'scheduled' then 'confirmed' when 'in_progress' then 'confirmed' else 'pending' end,
 h.facts->>'phase'
 from pro_work w cross join lateral (select public.pro_work_header_facts(p_owner,w.id) facts) h
 where w.user_id=p_owner and not exists(select 1 from pro_appointment_requests r where r.owner_id=p_owner and r.work_id=w.id and r.origin='booking')
 ), page as (
 select * from entries where (p_status='all' or status=p_status)
 and (p_after is null or (at,source,id)>((p_after->>'at')::timestamptz,p_after->>'source',p_after->>'id'))
 order by at,source,id limit 26
 ), visible as (select * from page order by at,source,id limit 25)
 select jsonb_build_object('items',coalesce((select jsonb_agg(to_jsonb(v)-'at' order by at,source,id) from visible v),'[]'::jsonb),
 'nextCursor',case when (select count(*) from page)>25 then (select jsonb_build_object('at',at,'source',source,'id',id) from visible order by at desc,source desc,id desc limit 1) else null end);
$$;
revoke all on function public.pro_work_header_facts(uuid,text),public.pro_work_header(uuid,text),public.pro_appointment_inbox(uuid,text,jsonb) from public,anon,authenticated;
grant execute on function public.pro_work_header_facts(uuid,text),public.pro_work_header(uuid,text),public.pro_appointment_inbox(uuid,text,jsonb) to service_role;
notify pgrst,'reload schema';
commit;

-- ===== client-view-finances-local.sql =====
-- LOCAL PRO ONLY. Round 4A (2026-11-13): real customer preview and a Finances section for the
-- linked customer. Read-only for money: no ledger, invoice, payment or estimate row is changed.
--
-- 1. show_finances: opt-in customer-view section, OFF by default like every section added after
--    the three basic ones (same compatibility rule: existing rows keep their current view).
--    Supersedes pro_client_dashboard_settings_json / _read / _mutate (client-dashboard-local.sql)
--    with the same signatures and only ADDED keys (showFinances, previewRequestId).
-- 2. pro_client_preview_actor: the owner of a job may run the customer readers of that job's
--    linked request AS that customer, so «Customer view › Preview» shows exactly what the customer
--    sees. Used only by GET readers (proCustomerReader); writes keep the caller as actor.
-- 3. pro_client_finances_client_read: quotes shared with this customer for the job, invoice
--    documents, payments received and the balance from the ONE formula (pro_work_account,
--    client-balance-local.sql). Never returns costs, margins, notes, labels or references.
begin;
alter table public.pro_client_dashboards add column if not exists show_finances boolean not null default false;

create or replace function public.pro_client_dashboard_settings_json(p_work text,p_row public.pro_client_dashboards) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('workId',p_work,'showUpdates',coalesce(p_row.show_updates,true),'showDailyLogs',coalesce(p_row.show_daily_logs,true),
 'showFiles',coalesce(p_row.show_files,true),'showAllowances',coalesce(p_row.show_allowances,false),'showSelections',coalesce(p_row.show_selections,false),'showSchedule',coalesce(p_row.show_schedule,false),'showPunchlist',coalesce(p_row.show_punchlist,false),'showContracts',coalesce(p_row.show_contracts,false),'showMoodBoards',coalesce(p_row.show_mood_boards,false),'showFinances',coalesce(p_row.show_finances,false),'welcomeText',p_row.welcome_text,'revision',coalesce(p_row.revision,0),'updatedAt',p_row.updated_at);
$$;

create or replace function public.pro_client_dashboard_read(p_actor uuid,p_work text) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare settings public.pro_client_dashboards;hist jsonb;recipient_name text;recipient_request uuid;
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if p_work is null or length(p_work) not between 1 and 160 then raise exception 'Invalid dashboard query' using errcode='22023';end if;
 if not exists(select 1 from public.pro_work where user_id=p_actor and id=p_work) then return null;end if;
 select * into settings from public.pro_client_dashboards where owner_id=p_actor and work_id=p_work;
 -- Same deterministic recipient as before; its request is the one the preview reads as the customer.
 select ar.client_name,ar.id into recipient_name,recipient_request from public.pro_appointment_requests ar join public.profiles c on c.id=ar.client_user_id
  where ar.owner_id=p_actor and ar.work_id=p_work and ar.status in('confirmed','completed') and not coalesce(c.is_disabled,false)
  order by ar.updated_at desc,ar.id desc limit 1;
 select coalesce(jsonb_agg(x.content order by x.revision desc),'[]'::jsonb) into hist from (
  select (h.after_settings->>'revision')::integer as revision,jsonb_build_object('actionId',h.action_id,'at',h.at,'before',h.before_settings,'after',h.after_settings) as content
  from public.pro_client_dashboard_history h where h.owner_id=p_actor and h.work_id=p_work order by (h.after_settings->>'revision')::integer desc limit 20
 ) x;
 return jsonb_build_object('settings',public.pro_client_dashboard_settings_json(p_work,settings),'history',hist,'recipientName',recipient_name,'previewRequestId',recipient_request);
end $$;

create or replace function public.pro_client_dashboard_mutate(p_actor uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare wid text;aid uuid;rev integer;keys text[];receipt public.pro_client_dashboard_actions;settings public.pro_client_dashboards;before_json jsonb;after_json jsonb;result jsonb;welcome text;allowances boolean;selections boolean;schedule boolean;punchlist boolean;contracts boolean;moodboards boolean;finances boolean;base_keys text[];
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if jsonb_typeof(p_input) is distinct from 'object' then raise exception 'Invalid dashboard' using errcode='22023';end if;
 select array_agg(key order by key) into keys from jsonb_object_keys(p_input) key;
 -- showAllowances and showSelections are optional so older clients keep working; when absent the stored value is kept.
 select array_agg(k order by k) into base_keys from unnest(keys) k where k not in('showAllowances','showSelections','showSchedule','showContracts','showPunchlist','showMoodBoards','showFinances');
 if base_keys is distinct from array['actionId','revision','showDailyLogs','showFiles','showUpdates','welcomeText','workId']
 or (p_input?'showAllowances' and jsonb_typeof(p_input->'showAllowances') is distinct from 'boolean')
 or (p_input?'showSelections' and jsonb_typeof(p_input->'showSelections') is distinct from 'boolean')
 or (p_input?'showSchedule' and jsonb_typeof(p_input->'showSchedule') is distinct from 'boolean')
 or (p_input?'showPunchlist' and jsonb_typeof(p_input->'showPunchlist') is distinct from 'boolean')
 or (p_input?'showContracts' and jsonb_typeof(p_input->'showContracts') is distinct from 'boolean')
 or (p_input?'showMoodBoards' and jsonb_typeof(p_input->'showMoodBoards') is distinct from 'boolean')
 or (p_input?'showFinances' and jsonb_typeof(p_input->'showFinances') is distinct from 'boolean')
 or jsonb_typeof(p_input->'workId') is distinct from 'string' or jsonb_typeof(p_input->'actionId') is distinct from 'string'
 or jsonb_typeof(p_input->'revision') is distinct from 'number' or not coalesce((p_input->>'revision')~'^[0-9]{1,10}$',false)
 or jsonb_typeof(p_input->'showUpdates') is distinct from 'boolean' or jsonb_typeof(p_input->'showDailyLogs') is distinct from 'boolean'
 or jsonb_typeof(p_input->'showFiles') is distinct from 'boolean' or jsonb_typeof(p_input->'welcomeText') not in('string','null') then raise exception 'Invalid dashboard fields' using errcode='22023';end if;
 if (p_input->>'revision')::numeric>2147483646 then raise exception 'Invalid revision' using errcode='22023';end if;
 wid:=p_input->>'workId';aid:=(p_input->>'actionId')::uuid;rev:=(p_input->>'revision')::integer;
 if length(wid) not between 1 and 160 then raise exception 'Invalid dashboard identity' using errcode='22023';end if;
 welcome:=nullif(btrim(coalesce(p_input->>'welcomeText','')),'');
 if welcome is not null and length(welcome)>1000 then raise exception 'Invalid welcome text' using errcode='22023';end if;
 if not exists(select 1 from public.pro_work where user_id=p_actor and id=wid) then raise exception 'Forbidden' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-client-dashboard-action:'||p_actor::text||':'||aid::text,0));
 select * into receipt from public.pro_client_dashboard_actions where actor_id=p_actor and action_id=aid;
 if found then
  if receipt.input is distinct from p_input then raise exception 'Action identity reused with different payload' using errcode='22023';end if;
  return receipt.result;
 end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-client-dashboard:'||p_actor::text||':'||wid,0));
 perform 1 from public.pro_work where user_id=p_actor and id=wid for update;
 if not found then raise exception 'Forbidden' using errcode='42501';end if;
 select * into settings from public.pro_client_dashboards where owner_id=p_actor and work_id=wid for update;
 if not found then
  if rev<>0 then raise exception 'Dashboard changed' using errcode='40001';end if;
  before_json:=null;allowances:=coalesce((p_input->>'showAllowances')::boolean,false);selections:=coalesce((p_input->>'showSelections')::boolean,false);
  schedule:=coalesce((p_input->>'showSchedule')::boolean,false);punchlist:=coalesce((p_input->>'showPunchlist')::boolean,false);contracts:=coalesce((p_input->>'showContracts')::boolean,false);moodboards:=coalesce((p_input->>'showMoodBoards')::boolean,false);finances:=coalesce((p_input->>'showFinances')::boolean,false);
  insert into public.pro_client_dashboards(owner_id,work_id,show_updates,show_daily_logs,show_files,show_allowances,show_selections,show_schedule,show_contracts,show_punchlist,show_mood_boards,show_finances,welcome_text)
   values(p_actor,wid,(p_input->>'showUpdates')::boolean,(p_input->>'showDailyLogs')::boolean,(p_input->>'showFiles')::boolean,allowances,selections,schedule,contracts,punchlist,moodboards,finances,welcome) returning * into settings;
 else
  if rev<>settings.revision then raise exception 'Dashboard changed' using errcode='40001';end if;
  before_json:=public.pro_client_dashboard_settings_json(wid,settings);allowances:=coalesce((p_input->>'showAllowances')::boolean,settings.show_allowances);selections:=coalesce((p_input->>'showSelections')::boolean,settings.show_selections);
  schedule:=coalesce((p_input->>'showSchedule')::boolean,settings.show_schedule);punchlist:=coalesce((p_input->>'showPunchlist')::boolean,settings.show_punchlist);contracts:=coalesce((p_input->>'showContracts')::boolean,settings.show_contracts);moodboards:=coalesce((p_input->>'showMoodBoards')::boolean,settings.show_mood_boards);finances:=coalesce((p_input->>'showFinances')::boolean,settings.show_finances);
  if settings.show_allowances=allowances and settings.show_selections=selections and settings.show_schedule=schedule and settings.show_punchlist=punchlist and settings.show_contracts=contracts and settings.show_mood_boards=moodboards and settings.show_finances=finances and settings.show_updates=(p_input->>'showUpdates')::boolean and settings.show_daily_logs=(p_input->>'showDailyLogs')::boolean
   and settings.show_files=(p_input->>'showFiles')::boolean and settings.welcome_text is not distinct from welcome then raise exception 'No dashboard changes' using errcode='22023';end if;
  update public.pro_client_dashboards set show_updates=(p_input->>'showUpdates')::boolean,show_daily_logs=(p_input->>'showDailyLogs')::boolean,
   show_files=(p_input->>'showFiles')::boolean,show_allowances=allowances,show_selections=selections,show_schedule=schedule,show_contracts=contracts,show_punchlist=punchlist,show_mood_boards=moodboards,show_finances=finances,welcome_text=welcome,revision=revision+1,updated_at=now() where owner_id=p_actor and work_id=wid returning * into settings;
 end if;
 after_json:=public.pro_client_dashboard_settings_json(wid,settings);result:=jsonb_build_object('settings',after_json);
 insert into public.pro_client_dashboard_history(owner_id,work_id,action_id,before_settings,after_settings) values(p_actor,wid,aid,before_json,after_json);
 insert into public.pro_client_dashboard_actions(actor_id,action_id,input,result) values(p_actor,aid,p_input,result);
 return result;
end $$;
-- The caller itself when it is the request's customer; the request's customer when the caller is
-- the owner of the request's job with Pro tools; otherwise null (the reader then decides as before).
create or replace function public.pro_client_preview_actor(p_actor uuid,p_request uuid) returns uuid
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare r public.pro_appointment_requests;
begin
 if p_actor is null or p_request is null then return null;end if;
 select * into r from public.pro_appointment_requests where id=p_request;
 if not found then return null;end if;
 if r.client_user_id=p_actor then return p_actor;end if;
 if r.owner_id=p_actor and r.work_id is not null and r.client_user_id is not null
  and exists(select 1 from public.pro_work w where w.user_id=p_actor and w.id=r.work_id)
  and coalesce(public.pro_private_work_tools_enabled(p_actor),false) then return r.client_user_id;end if;
 return null;
end $$;

create or replace function public.pro_client_finances_client_read(p_actor uuid,p_request uuid) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare owner uuid;wid text;req_status text;enabled boolean;w public.pro_work;account jsonb;quotes jsonb;invoices jsonb;payments jsonb;
begin
 if not exists(select 1 from public.profiles where id=p_actor and not coalesce(is_disabled,false)) then raise exception 'Forbidden' using errcode='42501';end if;
 select owner_id,work_id,status into owner,wid,req_status from public.pro_appointment_requests where id=p_request and client_user_id=p_actor and work_id is not null;
 if not found then return null;end if;
 select coalesce(show_finances,false) into enabled from public.pro_client_dashboards where owner_id=owner and work_id=wid;
 if req_status not in('confirmed','completed') or not coalesce(enabled,false) then return jsonb_build_object('visible',false);end if;
 select * into w from public.pro_work where user_id=owner and id=wid;
 if not found then return jsonb_build_object('visible',false);end if;
 account:=public.pro_work_account(owner,wid);
 -- Quotes: the latest live publication of each estimate of this project that THIS customer received.
 select coalesce(jsonb_agg(jsonb_build_object('id',x.id,'title',x.title,'version',x.version,'status',x.status,'totalCents',x.total,'currency',x.currency,'sharedAt',x.created_at) order by x.created_at desc),'[]'::jsonb) into quotes from (
  select distinct on (v.estimate_id) v.id,v.content->>'title' title,v.version,s.status,(v.content->>'totalCents')::bigint total,v.content->>'currency' currency,v.created_at
  from public.pro_project_estimate_rows(owner,w) e
  join public.pro_private_estimate_publications v on v.owner_id=owner and v.estimate_id=e.estimate_id
  join public.pro_private_estimate_publication_states s on s.publication_id=v.id
  where e.relation='project' and s.recipient_id=p_actor and s.status in('shared','changes_requested','accepted','declined')
  order by v.estimate_id,v.version desc) x;
 -- Invoice documents of this job (internal, not electronic invoices): title, date and total only.
 select coalesce(jsonb_agg(jsonb_build_object('id',d.id,'title',d.title,'createdAt',d.created_at,'totalCents',d.total_cents) order by d.created_at desc,d.id),'[]'::jsonb) into invoices
  from public.pro_invoice_drafts d left join public.pro_invoice_draft_management m on m.user_id=d.user_id and m.draft_id=d.id
  where d.user_id=owner and d.work_id=wid and not coalesce(m.archived,false);
 -- Payments received on the job ledger (the same rows the balance counts); a voided payment is marked.
 select coalesce(jsonb_agg(jsonb_build_object('id',e.id,'amountCents',e.amount_cents,'receivedOn',meta->'receivedOn','method',meta->'method','voided',voided,'recordedAt',e.created_at) order by e.created_at desc,e.id),'[]'::jsonb) into payments from (
  select e.*,public.pro_invoice_payment_metadata(owner,e.id) meta,exists(select 1 from public.pro_client_entries v where v.user_id=e.user_id and v.reversal_id=e.id and v.kind='payment_void') voided
  from public.pro_client_entries e where e.user_id=owner and e.work_id=wid and e.kind='payment') e;
 return jsonb_build_object('visible',true,'workTitle',w.service,
  'summary',jsonb_build_object('agreedCents',account->'agreedCents','paidCents',account->'paidCents','creditNotesCents',account->'creditNotesCents',
   'balanceCents',account->'customerBalanceCents','creditCents',greatest(-(account->>'balanceCents')::bigint,0),
   'invoicedCents',coalesce((select sum((i->>'totalCents')::bigint) from jsonb_array_elements(invoices) i),0)),
  'quotes',quotes,'invoices',invoices,'payments',payments);
end $$;

revoke all on function public.pro_client_dashboard_settings_json(text,public.pro_client_dashboards),public.pro_client_dashboard_read(uuid,text),public.pro_client_dashboard_mutate(uuid,jsonb),public.pro_client_preview_actor(uuid,uuid),public.pro_client_finances_client_read(uuid,uuid) from public,anon,authenticated;
grant execute on function public.pro_client_dashboard_settings_json(text,public.pro_client_dashboards),public.pro_client_dashboard_read(uuid,text),public.pro_client_dashboard_mutate(uuid,jsonb),public.pro_client_preview_actor(uuid,uuid),public.pro_client_finances_client_read(uuid,uuid) to service_role;
notify pgrst,'reload schema';
commit;

-- ===== work-overview-local.sql =====
-- LOCAL PRO ONLY. Round 4A (2026-11-13): job overview with widgets (project overview page).
-- One read-only RPC, one part per widget so each widget loads, fails and retries on its own:
--   client   – customer record contact, linked customer account, pending invitation, job phase
--   schedule – plan range, next open tasks (due date order), upcoming key dates
--   finance  – the ONE customer balance (pro_work_account, client-balance-local.sql), invoiced
--              (non-archived invoice documents of the job), costs and result exactly as
--              «Costs and payments» computes them (pro_work_costs_read summary); Round 7A adds the
--              agreed amount before VAT (agreedNetCents) so the result is shown like with like
--   activity – latest files, daily logs, updates and changes of the job
--   open     – open tasks / overdue, punch list, selections waiting for the customer, proposed
--              change, contracts shared and not answered, quotes shared and not answered,
--              allowances not decided
-- Owner only (pro_private_work_tools_enabled + own pro_work row). No row is written.
begin;
create or replace function public.pro_work_overview_read(p_actor uuid,p_work text,p_part text) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare w public.pro_work;c public.pro_clients;today date:=(clock_timestamp() at time zone 'America/Costa_Rica')::date;facts jsonb;costs jsonb;account jsonb;result jsonb;
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if p_work is null or length(p_work) not between 1 and 160 or p_part is null or p_part not in('client','schedule','finance','activity','open') then raise exception 'Invalid overview query' using errcode='22023';end if;
 select * into w from public.pro_work where user_id=p_actor and id=p_work;
 if not found then return null;end if;
 if p_part='client' then
  select * into c from public.pro_clients where user_id=p_actor and id=w."clientId";
  facts:=public.pro_work_header_facts(p_actor,p_work);
  return jsonb_build_object('workId',w.id,'part','client','phase',facts->'phase',
   'client',case when c.id is null then null else jsonb_build_object('id',c.id,'name',c.name,'email',nullif(c.email,''),'phone',nullif(c.phone,''),'address',nullif(c.address,''),'archived',c.archived) end,
   'linked',public.pro_work_client_link_json(p_actor,p_work),
   'pendingInvitation',exists(select 1 from public.pro_work_client_invitations i where i.owner_id=p_actor and i.work_id=p_work and public.pro_work_client_invitation_state(i)='active'));
 elsif p_part='schedule' then
  facts:=public.pro_work_header_facts(p_actor,p_work);
  return jsonb_build_object('workId',w.id,'part','schedule','planStart',facts->'planStart','planEnd',facts->'planEnd','today',today,
   -- Round 7B: a task planned in the schedule shows its period (not «No date»); order by due date, else planned end.
   'nextTasks',coalesce((select jsonb_agg(jsonb_build_object('id',x.id,'title',x.title,'dueDate',x.due_date,'plannedStart',x.planned_start,'plannedEnd',x.planned_end,'overdue',coalesce(x.due_date,x.planned_end) is not null and coalesce(x.due_date,x.planned_end)<today,'punch',x.punch) order by coalesce(x.due_date,x.planned_end) asc nulls last,x.id) from (
     select t.id,t.title,t.due_date,sp.planned_start,sp.planned_end,exists(select 1 from public.pro_work_punch_items p where p.owner_id=t.owner_id and p.work_id=t.work_id and p.task_id=t.id) punch
     from public.pro_work_tasks t left join public.pro_work_schedule_plans sp on sp.owner_id=t.owner_id and sp.work_id=t.work_id and sp.task_id=t.id
     where t.owner_id=p_actor and t.work_id=p_work and t.status='open' and not t.archived order by coalesce(t.due_date,sp.planned_end) asc nulls last,t.id limit 5) x),'[]'::jsonb),
   'openTasks',(select count(*) from public.pro_work_tasks t where t.owner_id=p_actor and t.work_id=p_work and t.status='open' and not t.archived),
   'keyDates',coalesce((select jsonb_agg(jsonb_build_object('id',m.id,'title',m.title,'date',m.milestone_date) order by m.milestone_date,m.id) from (
     select id,title,milestone_date from public.pro_work_schedule_milestones where owner_id=p_actor and work_id=p_work and not archived and milestone_date>=today order by milestone_date,id limit 3) m),'[]'::jsonb));
 elsif p_part='finance' then
  account:=public.pro_work_account(p_actor,p_work);
  costs:=public.pro_work_costs_read(p_actor,w."clientId",p_work)->'summary';
  return jsonb_build_object('workId',w.id,'part','finance',
   'agreedCents',account->'agreedCents','agreedSource',account->'agreedSource','paidCents',account->'paidCents','creditNotesCents',account->'creditNotesCents',
   'balanceCents',account->'customerBalanceCents','creditCents',greatest(-(account->>'balanceCents')::bigint,0),
   'invoicedCents',(select coalesce(sum(d.total_cents),0)::bigint from public.pro_invoice_drafts d left join public.pro_invoice_draft_management m on m.user_id=d.user_id and m.draft_id=d.id where d.user_id=p_actor and d.work_id=p_work and not coalesce(m.archived,false)),
   'invoiceCount',(select count(*) from public.pro_invoice_drafts d left join public.pro_invoice_draft_management m on m.user_id=d.user_id and m.draft_id=d.id where d.user_id=p_actor and d.work_id=p_work and not coalesce(m.archived,false)),
   'costCents',coalesce((costs->>'totalCostCents')::bigint,0),'committedCents',coalesce((costs->>'committedCents')::bigint,0),
   'resultCents',costs->'resultCents','resultWithCommittedCents',costs->'resultWithCommittedCents','resultBasis',costs->'resultBasis','agreedTaxCents',costs->'agreedTaxCents','agreedNetCents',costs->'agreedNetCents','uncostedCount',coalesce((costs->>'uncostedCount')::bigint,0));
 elsif p_part='activity' then
  select coalesce(jsonb_agg(a.doc order by a.at desc,a.id desc),'[]'::jsonb) into result from (
   select * from (
    (select f.id::text id,f.created_at at,jsonb_build_object('kind','file','id',f.id,'title',f.name,'at',f.created_at,'shared',f.published_at is not null) doc from public.pro_work_files f where f.owner_id=p_actor and f.work_id=p_work and f.ready order by f.created_at desc limit 4)
    union all
    (select l.id::text,l.created_at,jsonb_build_object('kind','daily_log','id',l.id,'title',coalesce(nullif(l.title,''),to_char(l.log_date,'YYYY-MM-DD')),'at',l.created_at,'date',l.log_date,'shared',l.published_revision is not null) from public.pro_daily_logs l where l.owner_id=p_actor and l.work_id=p_work and not l.archived order by l.created_at desc limit 4)
    union all
    (select u.id::text,u.updated_at,jsonb_build_object('kind','update','id',u.id,'title',u.title,'at',u.updated_at,'shared',u.published_revision is not null) from public.pro_work_updates u where u.owner_id=p_actor and u.work_id=p_work order by u.updated_at desc limit 4)
    union all
    (select g.id::text,g.updated_at,jsonb_build_object('kind','change','id',g.id,'title',g.reason,'at',g.updated_at,'status',g.status,'deltaCents',g.delta_cents) from public.pro_work_changes g where g.owner_id=p_actor and g.work_id=p_work order by g.updated_at desc limit 4)
   ) u order by at desc,id desc limit 8) a;
  return jsonb_build_object('workId',w.id,'part','activity','items',result);
 else
  return jsonb_build_object('workId',w.id,'part','open',
   'openTasks',(select count(*) from public.pro_work_tasks t where t.owner_id=p_actor and t.work_id=p_work and t.status='open' and not t.archived and not exists(select 1 from public.pro_work_punch_items p where p.owner_id=t.owner_id and p.work_id=t.work_id and p.task_id=t.id)),
   'overdueTasks',(select count(*) from public.pro_work_tasks t where t.owner_id=p_actor and t.work_id=p_work and t.status='open' and not t.archived and t.due_date<today),
   'punchOpen',(select count(*) from public.pro_work_punch_items p join public.pro_work_tasks t on t.owner_id=p.owner_id and t.work_id=p.work_id and t.id=p.task_id and not t.archived where p.owner_id=p_actor and p.work_id=p_work and t.status='open'),
   'punchTotal',(select count(*) from public.pro_work_punch_items p join public.pro_work_tasks t on t.owner_id=p.owner_id and t.work_id=p.work_id and t.id=p.task_id and not t.archived where p.owner_id=p_actor and p.work_id=p_work),
   'selectionsPending',(select count(*) from public.pro_work_selection_items s where s.owner_id=p_actor and s.work_id=p_work and public.pro_work_selection_state(s) in('pending_client','changes_requested')),
   'changesProposed',(select count(*) from public.pro_work_changes g where g.owner_id=p_actor and g.work_id=p_work and g.status='proposed'),
   'contractsShared',(select count(*) from public.pro_contracts k where k.owner_id=p_actor and k.work_id=p_work and k.status='shared'),
   'quotesWaiting',(select count(*) from public.pro_project_estimate_rows(p_actor,w) e join public.pro_private_estimate_publications v on v.owner_id=p_actor and v.estimate_id=e.estimate_id join public.pro_private_estimate_publication_states s on s.publication_id=v.id where e.relation='project' and s.status in('awaiting_claim','shared','changes_requested')),
   'allowancesPending',coalesce((public.pro_work_allowance_totals(p_actor,p_work)->>'pendingCount')::bigint,0));
 end if;
end $$;
revoke all on function public.pro_work_overview_read(uuid,text,text) from public,anon,authenticated;
grant execute on function public.pro_work_overview_read(uuid,text,text) to service_role;
notify pgrst,'reload schema';
commit;

-- ===== private-estimate-line-cost-local.sql =====
-- LOCAL PRO ONLY. Round 4A (2026-11-13): internal cost per quote line and line sections.
-- Lines may carry two OPTIONAL keys (old 8-key lines stay valid and unchanged):
--   unitCostCents – internal unit cost in cents (owner only). Margin = net (after discount, before
--                   tax) − qty × cost, computed in the editor. It never reaches a customer: every
--                   customer copy (publication snapshot, its copies, the accepted-job comparison)
--                   is built field by field in SQL without it, and the TS customer schemas omit it.
--   group         – section name; consecutive lines with the same name form a section with a
--                   subtotal in the editor, the owner preview and the owner's PDF. (Shared
--                   publications keep their existing hashed snapshot shape: see qa-review Ronda 4A.)
-- Supersedes pro_private_estimate_totals (private-estimates-local.sql: only the key check is relaxed
-- and the two keys validated; totals are unchanged) and pro_work_takeoff_line (takeoffs-local.sql:
-- a re-sent measurement keeps the line's cost and section).
begin;
create or replace function pro_private_estimate_totals(p_lines jsonb) returns jsonb language plpgsql immutable security invoker set search_path=public,pg_temp as $$declare l jsonb;b numeric;d numeric;n numeric;t numeric;s numeric:=0;ds numeric:=0;ts numeric:=0;tot numeric:=0;begin
 if jsonb_typeof(p_lines) is distinct from 'array' or jsonb_array_length(p_lines) not between 1 and 100 then raise exception 'Invalid lines' using errcode='22023';end if;
 if (select count(distinct value->>'id') from jsonb_array_elements(p_lines))<>jsonb_array_length(p_lines) then raise exception 'Duplicate line' using errcode='22023';end if;
 for l in select value from jsonb_array_elements(p_lines) loop
 if jsonb_typeof(l) is distinct from 'object' or (select array_agg(key order by key) from jsonb_object_keys(l)key where key not in('unitCostCents','group')) is distinct from array['catalogProductId','description','discountBps','id','qtyMilli','taxBps','unit','unitPriceCents'] or l->>'id' is null or length(btrim(l->>'description')) not between 1 and 2000 or length(l->>'unit')>30 then raise exception 'Invalid line fields' using errcode='22023';end if;
 -- Round 4A optional keys: unitCostCents (owner-only internal unit cost) and group (section name).
 if l?'unitCostCents' and (jsonb_typeof(l->'unitCostCents') is distinct from 'number' or not coalesce(l->>'unitCostCents'~'^[0-9]+$',false) or (l->>'unitCostCents')::numeric>10000000000) then raise exception 'Invalid line cost' using errcode='22023';end if;
 if l?'group' and (jsonb_typeof(l->'group') is distinct from 'string' or length(btrim(l->>'group')) not between 1 and 80 or l->>'group'<>btrim(l->>'group')) then raise exception 'Invalid line group' using errcode='22023';end if;
 perform (l->>'id')::uuid;if jsonb_typeof(l->'id') is distinct from 'string' or jsonb_typeof(l->'description') is distinct from 'string' or jsonb_typeof(l->'unit') is distinct from 'string' or jsonb_typeof(l->'catalogProductId') not in('null','string') or jsonb_typeof(l->'qtyMilli') is distinct from 'number' or jsonb_typeof(l->'unitPriceCents') is distinct from 'number' or jsonb_typeof(l->'discountBps') is distinct from 'number' or jsonb_typeof(l->'taxBps') is distinct from 'number' then raise exception 'Invalid line types' using errcode='22023';end if;
 if not coalesce(l->>'qtyMilli'~'^[0-9]+$',false) or not coalesce(l->>'unitPriceCents'~'^[0-9]+$',false) or not coalesce(l->>'discountBps'~'^[0-9]+$',false) or not coalesce(l->>'taxBps'~'^[0-9]+$',false) or (l->>'qtyMilli')::numeric not between 1 and 100000000 or (l->>'unitPriceCents')::numeric not between 0 and 10000000000 or (l->>'discountBps')::numeric not between 0 and 10000 or (l->>'taxBps')::numeric not between 0 and 10000 then raise exception 'Invalid line money' using errcode='22023';end if;
 b:=round((l->>'qtyMilli')::numeric*(l->>'unitPriceCents')::numeric/1000);d:=round(b*(l->>'discountBps')::numeric/10000);n:=b-d;t:=round(n*(l->>'taxBps')::numeric/10000);s:=s+b;ds:=ds+d;ts:=ts+t;tot:=tot+n+t;
 end loop;
 if greatest(s,ds,ts,tot)>9000000000000 then raise exception 'Estimate overflow' using errcode='22023';end if;return jsonb_build_object('subtotalCents',s,'discountCents',ds,'taxCents',ts,'totalCents',tot);end $$;

create or replace function public.pro_work_takeoff_line(p_actor uuid,p_estimate uuid,p_row public.pro_work_takeoff_measurements,p_old jsonb,p_en boolean) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare g public.pro_work_takeoff_pages;r jsonb;qty numeric;unit_label text;product public.pro_products;price bigint;cat text;line_id uuid;
begin
 select * into g from public.pro_work_takeoff_pages where owner_id=p_actor and plan_id=p_row.plan_id and page_number=p_row.page_number;
 r:=public.pro_work_takeoff_result(p_row,g);
 if (r->>'needsScale')::boolean then raise exception 'Calibrate the page before quoting' using errcode='22023';end if;
 qty:=(r->>'totalMilli')::numeric;
 if qty not between 1 and 100000000 then raise exception 'Quantity outside the estimate range' using errcode='22023';end if;
 unit_label:=case r->>'unit' when 'm2' then 'm²' when 'ft2' then 'ft²' when 'm' then 'm' when 'ft' then 'ft' else case when p_en then 'ea' else 'unid.' end end;
 select name into cat from public.pro_catalog_organizations where user_id=p_actor and kind='product_category' and id=p_row.category_id;
 line_id:=public.pro_work_takeoff_uuid('pro-work-takeoff-line:'||p_estimate::text||':'||p_row.id::text);
 price:=coalesce((p_old->>'unitPriceCents')::bigint,0);
 if p_row.product_id is not null then
  select * into product from public.pro_products where user_id=p_actor and id=p_row.product_id;
  -- A new link (or a line never sent) takes the item price; a price already edited in the estimate is kept.
  if found and not product.archived and (p_old is null or p_old->>'catalogProductId' is distinct from p_row.product_id) then
   price:=round(product.price*100);
   if price not between 0 and 10000000000 then raise exception 'Item price outside the estimate range' using errcode='22023';end if;
  end if;
 end if;
 return jsonb_build_object('id',line_id,'description',left(case when cat is null then p_row.name else cat||' · '||p_row.name end,2000),'unit',unit_label,
  'qtyMilli',qty::bigint,'unitPriceCents',price,'discountBps',coalesce((p_old->>'discountBps')::bigint,0),'taxBps',coalesce((p_old->>'taxBps')::bigint,0),
  'catalogProductId',case when p_row.product_id is not null and exists(select 1 from public.pro_products where user_id=p_actor and id=p_row.product_id and not archived) then to_jsonb(p_row.product_id) else coalesce(p_old->'catalogProductId','null'::jsonb) end)
  -- Round 4A: a re-sent measurement keeps the line's internal cost and section.
  ||jsonb_strip_nulls(jsonb_build_object('unitCostCents',case when jsonb_typeof(p_old->'unitCostCents')='number' then p_old->'unitCostCents' end,'group',case when jsonb_typeof(p_old->'group')='string' then p_old->'group' end));
end $$;
revoke all on function pro_private_estimate_totals(jsonb),public.pro_work_takeoff_line(uuid,uuid,public.pro_work_takeoff_measurements,jsonb,boolean) from public,anon,authenticated;
grant execute on function pro_private_estimate_totals(jsonb),public.pro_work_takeoff_line(uuid,uuid,public.pro_work_takeoff_measurements,jsonb,boolean) to service_role;
notify pgrst,'reload schema';
commit;

-- ===== work-billing-local.sql =====
-- LOCAL PRO ONLY. Round 4B (2026-11-13): invoicing from accepted quote lines, contract progress and
-- billable time/expenses; billable expense metadata (flag, payment method, VAT-included split, receipt)
-- and the person of a time entry (owner or a team member of the job).
--
-- * An invoice draft created here is an ordinary DIRECT draft (same writer chain as «Factura directa»:
--   pro_invoice_extras_save 'create_direct'), linked to its job (work_id) so it counts in «facturado».
--   Nothing is issued, sent or charged; the draft is internal.
-- * Each source used is recorded in pro_invoice_billing_items. While the draft is not archived its items
--   are ACTIVE: a time entry or expense can be in one active draft only (unique index); a quote line or
--   the agreed amount can be billed up to 100 % in total across active drafts. Archiving the draft
--   (the existing «Archivar», pro_invoice_management_save) releases them; restoring re-checks them.
-- * Amounts come from the existing single sources: the agreed amount and the customer balance from
--   pro_work_account (client-balance-local.sql, never forked), time from pro_time_entries + the live
--   line of the single ledger pro_work_cost_entries, expenses from pro_internal_expenses assigned to the job.
-- * Invoiced time/expenses are frozen: voiding/editing the time line, unlinking the expense or changing
--   its amount is refused (hint pro_billing_invoiced) until the draft is archived.
begin;

-- ---------------------------------------------------------------- expenses: billable metadata + receipt
create table if not exists public.pro_expense_billing(
 user_id uuid not null references public.profiles(id) on delete cascade,expense_id uuid not null,
 billable boolean not null default false,
 payment_method text check(payment_method is null or payment_method in('cash','transfer','card','sinpe','check','other')),
 vat_rate_bps integer check(vat_rate_bps is null or vat_rate_bps in(50,100,200,400,1300)),
 updated_at timestamptz not null default now(),
 primary key(user_id,expense_id),foreign key(user_id,expense_id) references public.pro_internal_expenses(user_id,id) on delete cascade
);
-- Round 7C: one «Registrar costo» form → the expense category is metadata too (optional).
alter table public.pro_expense_billing add column if not exists category text;
do $$begin if not exists(select 1 from pg_constraint where conname='pro_expense_billing_category_check') then
 alter table public.pro_expense_billing add constraint pro_expense_billing_category_check check(category is null or category in('materials','labor','subcontract','equipment','transport','permits','other'));end if;end $$;
create table if not exists public.pro_expense_receipts(
 user_id uuid not null references public.profiles(id) on delete cascade,expense_id uuid not null,id uuid not null,
 object_path text not null check(object_path ~ '^[a-f0-9-]{36}/[a-f0-9-]{36}\.(jpg|pdf)$'),
 name text not null check(length(name) between 1 and 160),mime_type text not null check(mime_type in('image/jpeg','application/pdf')),
 size_bytes integer not null check(size_bytes between 1 and 20971520),sha256 text not null check(sha256 ~ '^[a-f0-9]{64}$'),
 archived boolean not null default false,created_at timestamptz not null default now(),
 primary key(user_id,id),foreign key(user_id,expense_id) references public.pro_internal_expenses(user_id,id) on delete cascade,
 check(split_part(object_path,'/',1)=user_id::text and split_part(object_path,'/',2) like id::text||'.%')
);
create unique index if not exists pro_expense_receipts_one_active on public.pro_expense_receipts(user_id,expense_id) where not archived;

-- ---------------------------------------------------------------- time: person of an entry
create table if not exists public.pro_time_entry_people(
 owner_id uuid not null references public.profiles(id) on delete cascade,entry_id uuid not null,
 grant_id uuid,name text not null check(length(name) between 1 and 160),set_at timestamptz not null default now(),
 primary key(owner_id,entry_id),foreign key(owner_id,entry_id) references public.pro_time_entries(owner_id,id) on delete cascade
);

-- ---------------------------------------------------------------- billing items
create table if not exists public.pro_invoice_billing_items(
 user_id uuid not null,draft_id uuid not null,item_number integer not null check(item_number between 1 and 100),
 work_id text not null,
 source_type text not null check(source_type in('estimate_line','agreement','time','expense')),
 source_key text not null check(length(source_key) between 1 and 200),
 percent_bps integer check(percent_bps between 1 and 10000),
 amount_cents bigint not null check(amount_cents between 0 and 10000000000),
 description text not null check(length(description) between 1 and 200),
 active boolean not null default true,created_at timestamptz not null default now(),
 primary key(user_id,draft_id,item_number),
 foreign key(user_id,draft_id) references public.pro_invoice_drafts(user_id,id) on delete cascade,
 foreign key(user_id,work_id) references public.pro_work(user_id,id) on delete cascade,
 check((source_type in('estimate_line','agreement'))=(percent_bps is not null))
);
-- Double billing of a time entry or an expense is impossible while its draft is active.
create unique index if not exists pro_invoice_billing_once on public.pro_invoice_billing_items(user_id,source_type,source_key) where active and source_type in('time','expense');
create index if not exists pro_invoice_billing_work on public.pro_invoice_billing_items(user_id,work_id,source_type) where active;
create table if not exists public.pro_invoice_billing_requests(
 user_id uuid not null references public.profiles(id) on delete cascade,request_id uuid not null,input_hash text not null,draft_id uuid not null,
 created_at timestamptz not null default now(),primary key(user_id,request_id),
 foreign key(user_id,draft_id) references public.pro_invoice_drafts(user_id,id) on delete cascade
);

-- A quote line / the agreed amount: at most 100 % in total among ACTIVE drafts; never both kinds on one job.
create or replace function public.pro_invoice_billing_cap() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
declare used integer;
begin
 if not new.active then return new;end if;
 if new.source_type in('estimate_line','agreement') then
  select coalesce(sum(percent_bps),0) into used from public.pro_invoice_billing_items
   where user_id=new.user_id and source_type=new.source_type and source_key=new.source_key and active and not(draft_id=new.draft_id and item_number=new.item_number);
  if used+new.percent_bps>10000 then raise exception 'Already billed above 100 percent' using errcode='23505',hint='pro_billing_already';end if;
  if exists(select 1 from public.pro_invoice_billing_items where user_id=new.user_id and work_id=new.work_id and active
     and source_type=case new.source_type when 'agreement' then 'estimate_line' else 'agreement' end) then
   raise exception 'Job already billed by another method' using errcode='23505',hint='pro_billing_already';end if;
 end if;
 return new;
end $$;
drop trigger if exists pro_invoice_billing_cap on public.pro_invoice_billing_items;
create trigger pro_invoice_billing_cap before insert or update on public.pro_invoice_billing_items for each row execute function public.pro_invoice_billing_cap();

-- Archive releases, restore re-checks (unique index / cap raise 23505 → the restore is refused).
create or replace function public.pro_invoice_billing_sync() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
begin
 update public.pro_invoice_billing_items set active=not new.archived where user_id=new.user_id and draft_id=new.draft_id and active is distinct from not new.archived;
 return new;
end $$;
drop trigger if exists pro_invoice_billing_sync on public.pro_invoice_draft_management;
create trigger pro_invoice_billing_sync after insert or update of archived on public.pro_invoice_draft_management for each row execute function public.pro_invoice_billing_sync();

-- Live ledger line of an invoiced time entry / an invoiced expense is frozen.
create or replace function public.pro_invoice_billing_time_billed(p_owner uuid,p_line uuid) returns boolean
language sql stable security invoker set search_path=public,pg_temp as $$
 select exists(select 1 from public.pro_invoice_billing_items i join public.pro_time_entries e on e.owner_id=i.user_id and e.id::text=i.source_key
  where i.user_id=p_owner and i.active and i.source_type='time' and public.pro_time_live_line(e.owner_id,e.cost_entry_id)=p_line);
$$;
create or replace function public.pro_invoice_billing_expense_billed(p_owner uuid,p_expense uuid) returns boolean
language sql stable security invoker set search_path=public,pg_temp as $$
 select exists(select 1 from public.pro_invoice_billing_items i where i.user_id=p_owner and i.active and i.source_type='expense' and i.source_key=p_expense::text);
$$;
create or replace function public.pro_invoice_billing_guard_costs() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
begin
 if new.kind='time_void' and public.pro_invoice_billing_time_billed(new.user_id,new.reversal_id) then
  raise exception 'Invoiced time entry' using errcode='22023',hint='pro_billing_invoiced';end if;
 if new.kind='expense_unlink' and public.pro_invoice_billing_expense_billed(new.user_id,new.expense_id) then
  raise exception 'Invoiced expense' using errcode='22023',hint='pro_billing_invoiced';end if;
 return new;
end $$;
drop trigger if exists pro_invoice_billing_guard_costs on public.pro_work_cost_entries;
create trigger pro_invoice_billing_guard_costs before insert on public.pro_work_cost_entries for each row execute function public.pro_invoice_billing_guard_costs();
create or replace function public.pro_invoice_billing_guard_expense() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
begin
 if (new.amount_cents,new.expense_date,new.concept) is distinct from (old.amount_cents,old.expense_date,old.concept) and public.pro_invoice_billing_expense_billed(old.user_id,old.id) then
  raise exception 'Invoiced expense' using errcode='22023',hint='pro_billing_invoiced';end if;
 return new;
end $$;
drop trigger if exists pro_invoice_billing_guard_expense on public.pro_internal_expenses;
create trigger pro_invoice_billing_guard_expense before update on public.pro_internal_expenses for each row execute function public.pro_invoice_billing_guard_expense();

-- A direct draft may now belong to a job (billing drafts). Everything else of the direct contract stays.
alter table public.pro_invoice_drafts drop constraint if exists pro_invoice_drafts_direct_check;
alter table public.pro_invoice_drafts add constraint pro_invoice_drafts_direct_check check(source_kind<>'direct' or (source_id=id::text and quote_origin_key is null and basis='manual' and agreed_cents is null and paid_cents is null and balance_cents is null and material_count=0 and material_cost=0));

-- ---------------------------------------------------------------- expense summary (superseded, added keys only)
create or replace function public.pro_expense_summary(p_user uuid,p_id uuid) returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('id',e.id,'supplierId',e.supplier_id,'supplierName',e.supplier_name,'date',e.expense_date,'dueDate',e.due_date,'currency',e.currency,'concept',e.concept,'amountCents',e.amount_cents,'paidCents',v.paid,'balanceCents',e.amount_cents-v.paid,'status',case when v.paid=0 then 'pending' when v.paid=e.amount_cents then 'paid' else 'partial' end,
  'billable',coalesce(b.billable,false),'paymentMethod',b.payment_method,'vatRateBps',b.vat_rate_bps,'category',b.category,
  'netCents',case when b.vat_rate_bps is null then null else round(e.amount_cents*10000.0/(10000+b.vat_rate_bps))::bigint end,
  'vatCents',case when b.vat_rate_bps is null then null else e.amount_cents-round(e.amount_cents*10000.0/(10000+b.vat_rate_bps))::bigint end,
  'workId',(select a.work_id from pro_work_expense_assignments a where a.user_id=e.user_id and a.expense_id=e.id),
  'invoicedDraftId',(select i.draft_id from pro_invoice_billing_items i where i.user_id=e.user_id and i.active and i.source_type='expense' and i.source_key=e.id::text limit 1),
  'receipt',(select jsonb_build_object('id',r.id,'name',r.name,'mimeType',r.mime_type,'sizeBytes',r.size_bytes,'createdAt',r.created_at) from pro_expense_receipts r where r.user_id=e.user_id and r.expense_id=e.id and not r.archived))
 from pro_internal_expenses e cross join lateral(select coalesce(sum(case when kind='payment' then amount_cents else -amount_cents end),0)::bigint paid from pro_expense_payments where user_id=e.user_id and expense_id=e.id) v
 left join pro_expense_billing b on b.user_id=e.user_id and b.expense_id=e.id
 where e.user_id=p_user and e.id=p_id;
$$;

-- Expense writer with metadata: the original writer runs unchanged (same receipt/revision/CAS), then the
-- metadata is stored in the same transaction. Keys billable/paymentMethod/vatRateBps are optional.
create or replace function public.pro_expense_meta_save(p_user uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare result jsonb;meta_keys text[]:=array['billable','paymentMethod','vatRateBps','category'];old pro_expense_billing;v_billable boolean;v_method text;v_vat integer;v_category text;eid uuid;
begin
 if jsonb_typeof(p_input) is distinct from 'object' then raise exception 'Invalid expense' using errcode='22023';end if;
 if not(p_input ?| meta_keys) then return public.pro_expenses_save(p_user,p_input);end if;
 if p_input->>'action' is distinct from 'expense' then raise exception 'Metadata only for expenses' using errcode='22023';end if;
 if (p_input ? 'billable' and jsonb_typeof(p_input->'billable') is distinct from 'boolean')
  or (p_input ? 'paymentMethod' and jsonb_typeof(p_input->'paymentMethod') not in('string','null'))
  or (p_input ? 'vatRateBps' and jsonb_typeof(p_input->'vatRateBps') not in('number','null'))
  or (p_input ? 'category' and (jsonb_typeof(p_input->'category') not in('string','null') or p_input->>'category' not in('materials','labor','subcontract','equipment','transport','permits','other'))) then raise exception 'Invalid expense metadata' using errcode='22023';end if;
 eid:=(p_input->>'id')::uuid;
 select * into old from pro_expense_billing where user_id=p_user and expense_id=eid;
 v_billable:=case when p_input ? 'billable' then (p_input->>'billable')::boolean else coalesce(old.billable,false) end;
 v_method:=case when p_input ? 'paymentMethod' then p_input->>'paymentMethod' else old.payment_method end;
 v_vat:=case when p_input ? 'vatRateBps' then (p_input->>'vatRateBps')::integer else old.vat_rate_bps end;
 v_category:=case when p_input ? 'category' then p_input->>'category' else old.category end;
 if public.pro_invoice_billing_expense_billed(p_user,eid) and (v_billable is distinct from coalesce(old.billable,false) or v_vat is distinct from old.vat_rate_bps) then
  raise exception 'Invoiced expense' using errcode='22023',hint='pro_billing_invoiced';end if;
 result:=public.pro_expenses_save(p_user,p_input-meta_keys);
 insert into pro_expense_billing(user_id,expense_id,billable,payment_method,vat_rate_bps,category) values(p_user,eid,v_billable,v_method,v_vat,v_category)
  on conflict(user_id,expense_id) do update set billable=excluded.billable,payment_method=excluded.payment_method,vat_rate_bps=excluded.vat_rate_bps,category=excluded.category,updated_at=now();
 return result;
end $$;

-- Receipt (one active per expense; replacing archives the previous one). Bytes live in the private
-- bucket pro-expense-receipts under <owner>/<receipt>.<ext>; the route never returns storage URLs.
create or replace function public.pro_expense_receipt_mutate(p_user uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare eid uuid;rid uuid;ext text;row pro_expense_receipts;
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_user),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if jsonb_typeof(p_input) is distinct from 'object' or p_input->>'action' not in('attach','remove') then raise exception 'Invalid receipt' using errcode='22023';end if;
 eid:=(p_input->>'expenseId')::uuid;rid:=(p_input->>'receiptId')::uuid;
 perform 1 from pro_internal_expenses where user_id=p_user and id=eid for update;
 if not found then raise exception 'Forbidden' using errcode='42501';end if;
 if p_input->>'action'='remove' then
  update pro_expense_receipts set archived=true where user_id=p_user and expense_id=eid and id=rid and not archived;
  if not found then raise exception 'Receipt changed' using errcode='40001';end if;
  return jsonb_build_object('expenseId',eid,'receiptId',null);
 end if;
 select * into row from pro_expense_receipts where user_id=p_user and id=rid;
 if found then
  if row.expense_id<>eid or row.sha256<>p_input->>'sha256' then raise exception 'Receipt identity reused' using errcode='22023';end if;
  return jsonb_build_object('expenseId',eid,'receiptId',rid);
 end if;
 ext:=case p_input->>'mimeType' when 'application/pdf' then 'pdf' when 'image/jpeg' then 'jpg' end;
 if ext is null or p_input->>'objectPath'<>p_user::text||'/'||rid::text||'.'||ext then raise exception 'Invalid receipt path' using errcode='22023';end if;
 update pro_expense_receipts set archived=true where user_id=p_user and expense_id=eid and not archived;
 insert into pro_expense_receipts(user_id,expense_id,id,object_path,name,mime_type,size_bytes,sha256)
  values(p_user,eid,rid,p_input->>'objectPath',p_input->>'name',p_input->>'mimeType',(p_input->>'sizeBytes')::integer,p_input->>'sha256');
 return jsonb_build_object('expenseId',eid,'receiptId',rid);
end $$;
create or replace function public.pro_expense_receipt_download(p_user uuid,p_receipt uuid) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('objectPath',r.object_path,'name',r.name,'mimeType',r.mime_type,'sizeBytes',r.size_bytes,'sha256',r.sha256)
 from pro_expense_receipts r where r.user_id=p_user and r.id=p_receipt and coalesce(public.pro_private_work_tools_enabled(p_user),false);
$$;

-- ---------------------------------------------------------------- time: people and entry JSON
create or replace function public.pro_time_people(p_actor uuid,p_work text) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_array(jsonb_build_object('grantId',null,'name',coalesce(nullif(btrim(p.full_name),''),'Propietario'),'self',true))
  ||coalesce((select jsonb_agg(jsonb_build_object('grantId',g.id,'name',coalesce(nullif(btrim(g.member_name),''),'Miembro'),'self',false) order by lower(g.member_name),g.id)
   from pro_team_grants g where g.owner_id=p_actor and g.work_id=p_work and g.active),'[]'::jsonb)
 from profiles p where p.id=p_actor and exists(select 1 from pro_work w where w.user_id=p_actor and w.id=p_work);
$$;
create or replace function public.pro_time_entry_json(p_row public.pro_time_entries) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('id',p_row.id,'workId',p_row.work_id,'workTitle',(select w.service from public.pro_work w where w.user_id=p_row.owner_id and w.id=p_row.work_id),
  'activityId',p_row.activity_id,'activityName',(select a.name from public.pro_time_activities a where a.owner_id=p_row.owner_id and a.id=p_row.activity_id),
  'source',p_row.source,'status',p_row.status,'startedAt',p_row.started_at,'stoppedAt',p_row.stopped_at,'minutes',coalesce(l.minutes,p_row.minutes),
  'recordedOn',case when p_row.recorded_on is null then null else to_char(p_row.recorded_on,'YYYY-MM-DD') end,
  'billable',p_row.billable,'rateCents',p_row.rate_cents,'costCents',p_row.cost_cents,'note',p_row.note,'costEntryId',p_row.cost_entry_id,
  'billableCents',case when p_row.status='stopped' and p_row.billable and p_row.rate_cents is not null then round(coalesce(l.minutes,p_row.minutes)::numeric*p_row.rate_cents/60)::bigint end,
  'voided',p_row.cost_entry_id is not null and l.id is null,
  'adjusted',l.id is not null and l.id<>p_row.cost_entry_id,
  'revision',p_row.revision,
  'personGrantId',pp.grant_id,'personName',pp.name,
  'invoicedDraftId',(select i.draft_id from public.pro_invoice_billing_items i where i.user_id=p_row.owner_id and i.active and i.source_type='time' and i.source_key=p_row.id::text limit 1))
 from (select 1) one left join public.pro_work_cost_entries l on l.user_id=p_row.owner_id and l.id=public.pro_time_live_line(p_row.owner_id,p_row.cost_entry_id)
 left join public.pro_time_entry_people pp on pp.owner_id=p_row.owner_id and pp.entry_id=p_row.id;
$$;
-- Same time writer; 'personGrantId' (optional, start/manual) is stored with the entry in the same transaction.
create or replace function public.pro_time_mutate_person(p_actor uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare result jsonb;g pro_team_grants;who text;eid uuid;
begin
 if jsonb_typeof(p_input) is distinct from 'object' or not(p_input ? 'personGrantId') then return public.pro_time_mutate(p_actor,p_input);end if;
 if p_input->>'action' not in('start','manual') or jsonb_typeof(p_input->'personGrantId') not in('string','null') then raise exception 'Invalid time person' using errcode='22023';end if;
 result:=public.pro_time_mutate(p_actor,p_input-'personGrantId');
 eid:=(p_input->>'entryId')::uuid;
 if p_input->>'personGrantId' is null then
  select coalesce(nullif(btrim(full_name),''),'Propietario') into who from profiles where id=p_actor;
 else
  select * into g from pro_team_grants where id=(p_input->>'personGrantId')::uuid and owner_id=p_actor and work_id=p_input->>'workId' and active;
  if not found then raise exception 'Team member unavailable' using errcode='40001';end if;
  who:=coalesce(nullif(btrim(g.member_name),''),'Miembro');
 end if;
 insert into pro_time_entry_people(owner_id,entry_id,grant_id,name) values(p_actor,eid,g.id,left(who,160))
  on conflict(owner_id,entry_id) do nothing;
 return jsonb_set(result,'{entry}',public.pro_time_entry_json((select e from pro_time_entries e where e.owner_id=p_actor and e.id=eid)));
end $$;

-- ---------------------------------------------------------------- billing sources and writer
create or replace function public.pro_invoice_billing_vat(p_user uuid,p_work text) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select case d.default_vat_code when '01' then '{"t":"vat","r":"0"}' when '02' then '{"t":"vat","r":"1"}' when '03' then '{"t":"vat","r":"2"}' when '04' then '{"t":"vat","r":"4"}'
  when '08' then '{"t":"vat","r":"13"}' when '09' then '{"t":"vat","r":"0.5"}' when '10' then '{"t":"exempt","r":"0"}' when '11' then '{"t":"not_subject","r":"0"}' else null end::jsonb
 from (select 1) one left join pro_project_details d on d.owner_id=p_user and d.work_id=p_work;
$$;
create or replace function public.pro_invoice_billing_sources(p_user uuid,p_work text) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare w pro_work;c pro_clients;account jsonb;lines jsonb:='[]';agreement jsonb;times jsonb;expenses jsonb;drafts jsonb;billed bigint;v jsonb;pub uuid;
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_user),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if p_work is null or length(p_work) not between 1 and 160 then raise exception 'Invalid job' using errcode='22023';end if;
 select * into w from pro_work where user_id=p_user and id=p_work;
 if not found then return null;end if;
 select * into c from pro_clients where user_id=p_user and id=w."clientId";
 account:=public.pro_work_account(p_user,p_work);
 if account->>'agreedSource'='estimate' then
  select g.publication_id into pub from pro_private_estimate_work_agreements g where g.owner_id=p_user and g.work_id=p_work and g.currency='CRC';
  select coalesce(jsonb_agg(jsonb_build_object('key',pub::text||':'||(l->>'id'),'description',l->>'description','unit',l->>'unit','qtyMilli',(l->>'qtyMilli')::bigint,'unitPriceCents',(l->>'unitPriceCents')::bigint,
    'discountBps',(l->>'discountBps')::integer,'taxBps',(l->>'taxBps')::integer,'totalCents',t.total,
    'billedBps',coalesce((select sum(i.percent_bps) from pro_invoice_billing_items i where i.user_id=p_user and i.active and i.source_type='estimate_line' and i.source_key=pub::text||':'||(l->>'id')),0)) order by n),'[]'::jsonb)
   into lines
   from pro_private_estimate_publications v cross join lateral jsonb_array_elements(v.content->'lines') with ordinality e(l,n)
   cross join lateral (select round((l->>'qtyMilli')::numeric*(l->>'unitPriceCents')::numeric/1000) as base) a0
   cross join lateral (select a0.base-round(a0.base*(l->>'discountBps')::numeric/10000) as net) b
   cross join lateral (select (b.net+round(b.net*(l->>'taxBps')::numeric/10000))::bigint as total) t
   where v.id=pub;
 elsif account->>'agreedCents' is not null then
  agreement:=jsonb_build_object('key',p_work,'totalCents',(account->>'agreedCents')::bigint,'source',account->'agreedSource',
   'billedBps',coalesce((select sum(i.percent_bps) from pro_invoice_billing_items i where i.user_id=p_user and i.active and i.source_type='agreement' and i.source_key=p_work),0));
 end if;
 select coalesce(jsonb_agg(x order by x->>'date' desc,x->>'id'),'[]'::jsonb) into times from (
  select jsonb_build_object('id',e.id,'date',to_char(e.recorded_on,'YYYY-MM-DD'),'minutes',l.minutes,'rateCents',e.rate_cents,'amountCents',round(l.minutes::numeric*e.rate_cents/60)::bigint,
   'activityName',(select a.name from pro_time_activities a where a.owner_id=e.owner_id and a.id=e.activity_id),'personName',pp.name,'note',e.note,
   'invoicedDraftId',(select i.draft_id from pro_invoice_billing_items i where i.user_id=p_user and i.active and i.source_type='time' and i.source_key=e.id::text limit 1)) x
  from pro_time_entries e join pro_work_cost_entries l on l.user_id=e.owner_id and l.id=public.pro_time_live_line(e.owner_id,e.cost_entry_id)
  left join pro_time_entry_people pp on pp.owner_id=e.owner_id and pp.entry_id=e.id
  where e.owner_id=p_user and e.work_id=p_work and e.status='stopped' and e.billable and e.rate_cents is not null and e.rate_cents>0
  order by e.recorded_on desc,e.id limit 200) s;
 select coalesce(jsonb_agg(x order by x->>'date' desc,x->>'id'),'[]'::jsonb) into expenses from (
  select jsonb_build_object('id',x.id,'date',to_char(x.expense_date,'YYYY-MM-DD'),'concept',x.concept,'supplierName',x.supplier_name,'amountCents',x.amount_cents,'vatRateBps',b.vat_rate_bps,
   'netCents',case when b.vat_rate_bps is null then null else round(x.amount_cents*10000.0/(10000+b.vat_rate_bps))::bigint end,
   'invoicedDraftId',(select i.draft_id from pro_invoice_billing_items i where i.user_id=p_user and i.active and i.source_type='expense' and i.source_key=x.id::text limit 1)) x
  from pro_work_expense_assignments a join pro_internal_expenses x on x.user_id=a.user_id and x.id=a.expense_id join pro_expense_billing b on b.user_id=x.user_id and b.expense_id=x.id and b.billable
  where a.user_id=p_user and a.work_id=p_work order by x.expense_date desc,x.id limit 200) s;
 select coalesce(jsonb_agg(jsonb_build_object('id',d.id,'title',d.title,'totalCents',d.total_cents,'archived',coalesce(m.archived,false),'createdAt',d.created_at) order by d.created_at desc,d.id),'[]'::jsonb)
  into drafts from pro_invoice_drafts d left join pro_invoice_draft_management m on m.user_id=d.user_id and m.draft_id=d.id
  where d.user_id=p_user and d.work_id=p_work and exists(select 1 from pro_invoice_billing_items i where i.user_id=d.user_id and i.draft_id=d.id);
 select coalesce(sum(amount_cents),0) into billed from pro_invoice_billing_items where user_id=p_user and work_id=p_work and active and source_type in('estimate_line','agreement');
 v:=jsonb_build_object('workId',w.id,'clientId',w."clientId",'title',w.service,'cancelled',w.cancelled,'clientArchived',coalesce(c.archived,true),
  'agreedCents',account->'agreedCents','agreedSource',account->'agreedSource','customerBalanceCents',account->'customerBalanceCents','paidCents',account->'paidCents',
  'billedContractCents',billed,'lines',lines,'agreement',agreement,'time',times,'expenses',expenses,'defaultVat',public.pro_invoice_billing_vat(p_user,p_work));
 return v||jsonb_build_object('fingerprint',md5(v::text),'drafts',drafts);
end $$;

create or replace function public.pro_invoice_billing_create(p_user uuid,p_input jsonb) returns uuid
language plpgsql security invoker set search_path=public,pg_temp as $$
declare s jsonb;rid uuid;hash text;prior pro_invoice_billing_requests;keys text[];out_lines jsonb:='[]';items jsonb:='[]';l jsonb;sel jsonb;bps integer;n integer:=0;
 vat jsonb;t jsonb;x jsonb;draft uuid;price numeric;amount bigint;
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_user),false) then raise exception 'Forbidden' using errcode='42501';end if;
 keys:=array['action','requestId','workId','fingerprint','title','notes','lines','agreementBps','timeIds','expenseIds'];
 if jsonb_typeof(p_input) is distinct from 'object' or p_input->>'action' is distinct from 'create_billing' or not(p_input ?& keys) or (p_input-keys)<>'{}'::jsonb
  or jsonb_typeof(p_input->'lines') is distinct from 'array' or jsonb_typeof(p_input->'timeIds') is distinct from 'array' or jsonb_typeof(p_input->'expenseIds') is distinct from 'array'
  or jsonb_typeof(p_input->'agreementBps') not in('number','null') or jsonb_typeof(p_input->'title') is distinct from 'string' or jsonb_typeof(p_input->'notes') is distinct from 'string'
  or length(btrim(p_input->>'title')) not between 1 and 160 or length(p_input->>'notes')>2000 then raise exception 'Invalid billing request' using errcode='22023';end if;
 rid:=(p_input->>'requestId')::uuid;hash:=md5((p_input-'requestId')::text);
 -- Same owner lock as every invoice writer (archive/restore included).
 perform pg_advisory_xact_lock(hashtextextended(p_user::text,0));
 select * into prior from pro_invoice_billing_requests where user_id=p_user and request_id=rid;
 if found then if prior.input_hash<>hash then raise exception 'Request already used' using errcode='22023';end if;return prior.draft_id;end if;
 if exists(select 1 from pro_invoice_drafts where user_id=p_user and id=rid) then raise exception 'Request collision' using errcode='40001';end if;
 s:=public.pro_invoice_billing_sources(p_user,p_input->>'workId');
 if s is null then raise exception 'Forbidden' using errcode='42501';end if;
 if (s->>'cancelled')::boolean or (s->>'clientArchived')::boolean then raise exception 'Inactive job' using errcode='22023';end if;
 if s->>'fingerprint' is distinct from p_input->>'fingerprint' then raise exception 'Billing sources changed' using errcode='40001';end if;
 vat:=s->'defaultVat';
 -- (a) accepted quote lines, full or % per line
 for sel in select value from jsonb_array_elements(p_input->'lines') loop
  if jsonb_typeof(sel) is distinct from 'object' or (sel-array['key','bps'])<>'{}'::jsonb or jsonb_typeof(sel->'bps') is distinct from 'number' or (sel->>'bps')!~'^[0-9]{1,5}$' then raise exception 'Invalid line' using errcode='22023';end if;
  bps:=(sel->>'bps')::integer;
  select value into l from jsonb_array_elements(s->'lines') where value->>'key'=sel->>'key';
  if l is null or bps<1 or bps>10000-(l->>'billedBps')::integer then raise exception 'Line already billed or unavailable' using errcode='40001';end if;
  if exists(select 1 from jsonb_array_elements(p_input->'lines') o where o->>'key'=sel->>'key' having count(*)>1) then raise exception 'Duplicate line' using errcode='22023';end if;
  n:=n+1;price:=round((l->>'unitPriceCents')::numeric*bps/1000000,5);amount:=round((l->>'totalCents')::numeric*bps/10000);
  out_lines:=out_lines||jsonb_build_object('kind','service','productId',null,'sku','','description',left(l->>'description'||case when bps<10000 then ' ('||trim(to_char(bps/100.0,'FM990.99'),'.')||' %)' else '' end,200),
   'unit',coalesce(nullif(left(l->>'unit',30),''),'Sp'),'cabys','','quantity',trim_scale((l->>'qtyMilli')::numeric/1000)::text,'unitPrice',trim_scale(price)::text,'discountType','percent','discount',trim_scale((l->>'discountBps')::numeric/100)::text,'discountReason','',
   'taxTreatment',case when (l->>'taxBps')::integer>0 then 'vat' else 'pending' end,'taxRate',trim_scale((l->>'taxBps')::numeric/100)::text);
  items:=items||jsonb_build_object('type','estimate_line','key',l->>'key','bps',bps,'amount',amount,'description',left(l->>'description',200));
 end loop;
 -- (b) progress % of the agreed amount (when there are no accepted quote lines)
 if p_input->>'agreementBps' is not null then
  if (p_input->>'agreementBps')!~'^[0-9]{1,5}$' then raise exception 'Invalid progress' using errcode='22023';end if;
  bps:=(p_input->>'agreementBps')::integer;l:=s->'agreement';
  if l is null or l='null'::jsonb or bps<1 or bps>10000-(l->>'billedBps')::integer then raise exception 'Progress already billed or unavailable' using errcode='40001';end if;
  n:=n+1;amount:=round((l->>'totalCents')::numeric*bps/10000);
  out_lines:=out_lines||jsonb_build_object('kind','service','productId',null,'sku','','description',left(s->>'title',170)||' — '||trim(to_char(bps/100.0,'FM990.99'),'.')||' %','unit','Sp','cabys','','quantity','1',
   'unitPrice',trim_scale(round((l->>'totalCents')::numeric*bps/1000000,5))::text,'discountType','percent','discount','0','discountReason','',
   -- Fix 13: the progress line takes the project's default IVA like time lines (still «por definir» without one).
   'taxTreatment',coalesce(vat->>'t','pending'),'taxRate',coalesce(vat->>'r','0'));
  items:=items||jsonb_build_object('type','agreement','key',l->>'key','bps',bps,'amount',amount,'description',left(s->>'title',200));
 end if;
 -- (c) unbilled billable time
 for sel in select value from jsonb_array_elements(p_input->'timeIds') loop
  select value into t from jsonb_array_elements(s->'time') where value->>'id'=sel#>>'{}';
  if t is null or t->>'invoicedDraftId' is not null then raise exception 'Time entry already billed or unavailable' using errcode='40001';end if;
  if exists(select 1 from jsonb_array_elements(p_input->'timeIds') o where o=sel having count(*)>1) then raise exception 'Duplicate time entry' using errcode='22023';end if;
  n:=n+1;
  out_lines:=out_lines||jsonb_build_object('kind','service','productId',null,'sku','','description',left(concat_ws(' · ',coalesce(t->>'activityName','Horas'),t->>'personName',t->>'date',
    (((t->>'minutes')::integer/60)::text||' h '||lpad(((t->>'minutes')::integer%60)::text,2,'0')||' min'),nullif(t->>'note','')),200),
   'unit','h','cabys','','quantity','1','unitPrice',trim_scale((t->>'amountCents')::numeric/100)::text,'discountType','percent','discount','0','discountReason','',
   'taxTreatment',coalesce(vat->>'t','pending'),'taxRate',coalesce(vat->>'r','0'));
  items:=items||jsonb_build_object('type','time','key',t->>'id','bps',null,'amount',(t->>'amountCents')::bigint,'description',left(coalesce(t->>'activityName','Horas')||' · '||(t->>'date'),200));
 end loop;
 -- (c) unbilled billable expenses (VAT-included split when the expense says so)
 for sel in select value from jsonb_array_elements(p_input->'expenseIds') loop
  select value into x from jsonb_array_elements(s->'expenses') where value->>'id'=sel#>>'{}';
  if x is null or x->>'invoicedDraftId' is not null then raise exception 'Expense already billed or unavailable' using errcode='40001';end if;
  if exists(select 1 from jsonb_array_elements(p_input->'expenseIds') o where o=sel having count(*)>1) then raise exception 'Duplicate expense' using errcode='22023';end if;
  n:=n+1;
  out_lines:=out_lines||jsonb_build_object('kind','service','productId',null,'sku','','description',left(concat_ws(' · ',x->>'concept',x->>'supplierName',x->>'date'),200),'unit','Sp','cabys','','quantity','1',
   'unitPrice',trim_scale(coalesce((x->>'netCents')::numeric,(x->>'amountCents')::numeric)/100)::text,'discountType','percent','discount','0','discountReason','',
   'taxTreatment',case when x->>'vatRateBps' is not null then 'vat' else 'pending' end,'taxRate',case when x->>'vatRateBps' is not null then trim_scale((x->>'vatRateBps')::numeric/100)::text else '0' end);
  items:=items||jsonb_build_object('type','expense','key',x->>'id','bps',null,'amount',(x->>'amountCents')::bigint,'description',left(x->>'concept',200));
 end loop;
 if n=0 then raise exception 'Choose what to bill' using errcode='22023';end if;
 if n>100 then raise exception 'Too many lines' using errcode='22023';end if;
 -- The same writer chain as a direct draft (receiver, fiscal defaults, totals, VAT), then the job link.
 draft:=public.pro_invoice_extras_save(p_user,jsonb_build_object('action','create_direct','requestId',rid,'clientId',s->>'clientId','title',btrim(p_input->>'title'),'notes',p_input->>'notes','lines',out_lines));
 update pro_invoice_drafts set work_id=s->>'workId' where user_id=p_user and id=draft;
 insert into pro_invoice_billing_items(user_id,draft_id,item_number,work_id,source_type,source_key,percent_bps,amount_cents,description)
  select p_user,draft,k,s->>'workId',i->>'type',i->>'key',(i->>'bps')::integer,(i->>'amount')::bigint,i->>'description' from jsonb_array_elements(items) with ordinality e(i,k);
 insert into pro_invoice_billing_requests(user_id,request_id,input_hash,draft_id) values(p_user,rid,hash,draft);
 return draft;
end $$;

-- ---------------------------------------------------------------- RLS, grants, bucket
do $$declare n text;begin foreach n in array array['pro_expense_billing','pro_expense_receipts','pro_time_entry_people','pro_invoice_billing_items','pro_invoice_billing_requests'] loop
 execute format('alter table public.%I enable row level security',n);execute format('revoke all on public.%I from public,anon,authenticated',n);execute format('grant all on public.%I to service_role',n);
 end loop;end $$;
revoke all on function public.pro_invoice_billing_cap(),public.pro_invoice_billing_sync(),public.pro_invoice_billing_time_billed(uuid,uuid),public.pro_invoice_billing_expense_billed(uuid,uuid),public.pro_invoice_billing_guard_costs(),public.pro_invoice_billing_guard_expense(),
 public.pro_expense_summary(uuid,uuid),public.pro_expense_meta_save(uuid,jsonb),public.pro_expense_receipt_mutate(uuid,jsonb),public.pro_expense_receipt_download(uuid,uuid),public.pro_time_people(uuid,text),public.pro_time_entry_json(public.pro_time_entries),public.pro_time_mutate_person(uuid,jsonb),
 public.pro_invoice_billing_vat(uuid,text),public.pro_invoice_billing_sources(uuid,text),public.pro_invoice_billing_create(uuid,jsonb) from public,anon,authenticated;
grant execute on function public.pro_invoice_billing_time_billed(uuid,uuid),public.pro_invoice_billing_expense_billed(uuid,uuid),
 public.pro_expense_summary(uuid,uuid),public.pro_expense_meta_save(uuid,jsonb),public.pro_expense_receipt_mutate(uuid,jsonb),public.pro_expense_receipt_download(uuid,uuid),public.pro_time_people(uuid,text),public.pro_time_entry_json(public.pro_time_entries),public.pro_time_mutate_person(uuid,jsonb),
 public.pro_invoice_billing_vat(uuid,text),public.pro_invoice_billing_sources(uuid,text),public.pro_invoice_billing_create(uuid,jsonb) to service_role;
do $$begin
 if to_regclass('storage.buckets') is not null then
  insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('pro-expense-receipts','pro-expense-receipts',false,20971520,array['image/jpeg','application/pdf']) on conflict(id) do update set file_size_limit=excluded.file_size_limit;
  if not exists(select 1 from storage.buckets where id='pro-expense-receipts' and not public and file_size_limit=20971520 and cardinality(allowed_mime_types)=2 and allowed_mime_types @> array['image/jpeg','application/pdf']) then raise exception 'Expense receipts bucket configuration must match the private contract';end if;
 end if;
 if to_regclass('storage.objects') is not null then
  execute 'drop policy if exists pro_expense_receipts_no_direct on storage.objects';
  execute 'create policy pro_expense_receipts_no_direct on storage.objects as restrictive for all to anon,authenticated using (bucket_id <> ''pro-expense-receipts'') with check (bucket_id <> ''pro-expense-receipts'')';
 end if;
end $$;
notify pgrst,'reload schema';
commit;

-- ===== work-tasks-gantt-local.sql =====
-- LOCAL PRO ONLY. Round 4B (2026-11-13): task assignee from the Team and Gantt editing.
-- (1) pro_work_task_assignees: read-only options for the "Responsable" selector of a job task:
--     the job's team members (grants; only active contributors can be assigned, as enforced by
--     pro_team_task_assign), people of the owner's team on OTHER jobs without a grant on this
--     job (shown disabled: invite them from Team first) and the current real assignment of the
--     listed tasks. The legacy free-text `assignee` column is never changed here.
-- (2) pro_work_timeline_task_create: creates a job task and its planned period in ONE
--     transaction through the two existing writers (pro_work_tasks_mutate 'create' and
--     pro_work_schedule_mutate 'task_plan'). Idempotent: both inner action ids derive from the
--     caller's actionId, so a retry replays both receipts; the schedule revision is the CAS
--     (40001 → 409). No table is created; no notification is sent.
begin;
create or replace function public.pro_work_task_assignees(p_actor uuid,p_work text,p_tasks uuid[]) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare members jsonb;others jsonb;assignments jsonb;
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if p_work is null or length(p_work) not between 1 and 160 or p_tasks is null or cardinality(p_tasks)>20 or array_position(p_tasks,null) is not null then raise exception 'Invalid assignee query' using errcode='22023';end if;
 if not exists(select 1 from public.pro_work where user_id=p_actor and id=p_work) then return null;end if;
 select coalesce(jsonb_agg(jsonb_build_object('grantId',g.id,'name',g.member_name,'role',g.role,'active',g.active,
   'canAssign',g.active and g.role='contributor' and exists(select 1 from public.profiles p where p.id=g.member_user_id and not coalesce(p.is_disabled,false))) order by g.active desc,lower(g.member_name),g.id),'[]'::jsonb)
  into members from (select * from public.pro_team_grants where owner_id=p_actor and work_id=p_work order by active desc,lower(member_name),id limit 50) g;
 select coalesce(jsonb_agg(jsonb_build_object('name',o.member_name) order by lower(o.member_name)),'[]'::jsonb) into others from (
  select distinct on (g.member_user_id) g.member_user_id,g.member_name from public.pro_team_grants g
  where g.owner_id=p_actor and g.work_id<>p_work and g.active and length(btrim(g.member_name))>0
   and not exists(select 1 from public.pro_team_grants h where h.owner_id=p_actor and h.work_id=p_work and h.member_user_id=g.member_user_id)
  order by g.member_user_id,g.updated_at desc limit 20) o;
 select coalesce(jsonb_object_agg(t.id::text,public.pro_team_assignment_json(p_actor,t.id)) filter(where a.task_id is not null),'{}'::jsonb) into assignments
  from public.pro_work_tasks t left join public.pro_team_task_assignments a on a.owner_id=t.owner_id and a.task_id=t.id
  where t.owner_id=p_actor and t.work_id=p_work and t.id=any(p_tasks);
 return jsonb_build_object('workId',p_work,'members',members,'others',others,'assignments',assignments);
end $$;

create or replace function public.pro_work_timeline_task_create(p_actor uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare keys text[];aid uuid;tid uuid;wid text;task_answer jsonb;plan_answer jsonb;
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if jsonb_typeof(p_input) is distinct from 'object' then raise exception 'Invalid timeline task' using errcode='22023';end if;
 select array_agg(key order by key) into keys from jsonb_object_keys(p_input) key;
 if keys is distinct from array['action','actionId','phaseId','plannedEnd','plannedStart','revision','taskId','title','workId'] or p_input->>'action' is distinct from 'timeline_task_create'
  or jsonb_typeof(p_input->'actionId') is distinct from 'string' or jsonb_typeof(p_input->'taskId') is distinct from 'string' or jsonb_typeof(p_input->'workId') is distinct from 'string'
  or jsonb_typeof(p_input->'title') is distinct from 'string' or jsonb_typeof(p_input->'plannedStart') is distinct from 'string' or jsonb_typeof(p_input->'plannedEnd') is distinct from 'string'
  or jsonb_typeof(p_input->'phaseId') not in('string','null') or jsonb_typeof(p_input->'revision') is distinct from 'number' then raise exception 'Invalid timeline task fields' using errcode='22023';end if;
 aid:=(p_input->>'actionId')::uuid;tid:=(p_input->>'taskId')::uuid;wid:=p_input->>'workId';
 task_answer:=public.pro_work_tasks_mutate(p_actor,jsonb_build_object('action','create','workId',wid,'taskId',tid,
  'actionId',overlay(overlay(md5('timeline-task:'||aid::text) placing '4' from 13) placing '8' from 17)::uuid,'revision',0,
  'title',p_input->>'title','details','','dueDate',null,'assignee',''));
 plan_answer:=public.pro_work_schedule_mutate(p_actor,jsonb_build_object('action','task_plan','workId',wid,'taskId',tid,
  'actionId',overlay(overlay(md5('timeline-plan:'||aid::text) placing '4' from 13) placing '8' from 17)::uuid,'revision',p_input->'revision',
  'phaseId',p_input->'phaseId','plannedStart',p_input->>'plannedStart','plannedEnd',p_input->>'plannedEnd','dependsOn','[]'::jsonb));
 return jsonb_build_object('action','timeline_task_create','workId',wid,'task',task_answer->'task','plan',plan_answer);
end $$;
revoke all on function public.pro_work_task_assignees(uuid,text,uuid[]),public.pro_work_timeline_task_create(uuid,jsonb) from public,anon,authenticated;
grant execute on function public.pro_work_task_assignees(uuid,text,uuid[]),public.pro_work_timeline_task_create(uuid,jsonb) to service_role;
notify pgrst,'reload schema';
commit;

-- ===== bid-portal-files-local.sql =====
-- LOCAL PRO ONLY. Round 4B (2026-11-13): attachments a vendor sends with its offer from the bid
-- portal, and the award notice the vendor sees there. Builds on bid-vendor-portal-local.sql.
--  * Same file contract as job files (work-files-local.sql): private bucket of its own
--    ('pro-bid-portal-files'), JPG (re-encoded, at most 2 MB) or PDF (at most 3 MB), canonical
--    name, SHA-256 of the raw and of the stored bytes, object path <owner>/<file id>.<ext>; the
--    server reserves the row, uploads, verifies the stored bytes and only then marks it ready.
--    No signed or public URL: every download is reauthorized by the route.
--  * Readable ONLY by the owner of the bid (Pro tools enabled) and by the vendor it belongs to
--    (a valid, unrevoked, unexpired portal session of that same owner, package and vendor). Any
--    other vendor (other invitation or other owner's link) and any other owner get nothing.
--  * The vendor uploads and removes its own files while the bid is open and not past its due
--    date (Costa Rica day). Up to 10 active files per vendor and package; at most 50 reservations
--    per link. A removed file stops being listed or downloadable for both sides.
--  * A vendor with portal attachments cannot be removed from the package (same rule and hint as
--    portal offers: the record is kept; cancel its link instead).
--  * Award notice: once the package is awarded the vendor sees whether it was awarded the whole
--    package, some items (with its own awarded total) or was not selected; cancelled bids say so.
--    Never other vendors, their prices or the comparison. Nothing is e-mailed or sent.
-- Lock order (reserve/remove): bid work advisory 'pro-bid-work:<owner>:<work>' first, then the link
-- row, as pro_bid_portal_submit. Reapplicable.
begin;
create table if not exists public.pro_bid_portal_files(
 id uuid primary key,owner_id uuid not null references public.profiles(id) on delete cascade,
 package_id uuid not null,supplier_id uuid not null,link_id uuid not null,
 source_name text not null check(length(source_name) between 1 and 160 and source_name !~ '[[:cntrl:]/]' and position(chr(92) in source_name)=0),
 name text not null check(length(name) between 1 and 160 and name !~ '[[:cntrl:]/]' and position(chr(92) in name)=0),
 mime_type text not null check(mime_type in('image/jpeg','application/pdf')),
 raw_sha256 text not null check(raw_sha256~'^[a-f0-9]{64}$'),sha256 text not null check(sha256~'^[a-f0-9]{64}$'),
 size_bytes integer not null check(size_bytes>0 and size_bytes<=20971520),object_path text not null unique,
 ready boolean not null default false,ready_at timestamptz,removed_at timestamptz,created_at timestamptz not null default now(),
 foreign key(owner_id,package_id,supplier_id) references public.pro_bid_invitations(owner_id,package_id,supplier_id) on delete cascade,
 foreign key(owner_id,link_id) references public.pro_bid_portal_links(owner_id,id) on delete cascade,
 check(mime_type<>'image/jpeg' or size_bytes<=20971520),
 check(object_path=owner_id::text||'/'||id::text||case when mime_type='application/pdf' then '.pdf' else '.jpg' end),
 check(right(name,4)=case when mime_type='application/pdf' then '.pdf' else '.jpg' end),
 check(ready=(ready_at is not null)),check(removed_at is null or ready)
);
create index if not exists pro_bid_portal_files_vendor on public.pro_bid_portal_files(owner_id,package_id,supplier_id,created_at,id);
create index if not exists pro_bid_portal_files_link on public.pro_bid_portal_files(owner_id,link_id);

-- Valid vendor session (same checks as pro_bid_portal_view), or a row of nulls.
create or replace function public.pro_bid_portal_session_link(p_session_hash text) returns public.pro_bid_portal_links
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare l public.pro_bid_portal_links;
begin
 select * into l from public.pro_bid_portal_links where session_hash=public.pro_bid_portal_hash(p_session_hash);
 if not found or l.revoked_at is not null or l.expires_at<=now() or not coalesce(public.pro_private_work_tools_enabled(l.owner_id),false)
  or not exists(select 1 from public.pro_bid_invitations i where i.owner_id=l.owner_id and i.package_id=l.package_id and i.supplier_id=l.supplier_id) then
  l:=null;
 end if;
 return l;
end $$;
create or replace function public.pro_bid_portal_file_json(p_row public.pro_bid_portal_files) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('id',p_row.id,'name',p_row.name,'mimeType',p_row.mime_type,'sizeBytes',p_row.size_bytes,'sha256',p_row.sha256,'createdAt',p_row.created_at) $$;
create or replace function public.pro_bid_portal_file_download_json(p_row public.pro_bid_portal_files) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('objectPath',p_row.object_path,'name',p_row.name,'mimeType',p_row.mime_type,'sizeBytes',p_row.size_bytes,'sha256',p_row.sha256) $$;

-- Vendor: reserve one upload (route checks and normalizes the bytes first).
create or replace function public.pro_bid_portal_file_reserve(p_session_hash text,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare l public.pro_bid_portal_links;r public.pro_bid_packages;f public.pro_bid_portal_files;keys text[];fid uuid;ext text;today date:=public.pro_bid_today();
begin
 if jsonb_typeof(p_input) is distinct from 'object' then raise exception 'Invalid file' using errcode='22023';end if;
 select array_agg(key order by key) into keys from jsonb_object_keys(p_input) key;
 if keys is distinct from array['fileId','mimeType','name','rawSha256','sha256','sizeBytes','sourceName'] or jsonb_typeof(p_input->'sizeBytes') is distinct from 'number'
  or jsonb_typeof(p_input->'name') is distinct from 'string' or jsonb_typeof(p_input->'sourceName') is distinct from 'string' or jsonb_typeof(p_input->'mimeType') is distinct from 'string'
  or jsonb_typeof(p_input->'sha256') is distinct from 'string' or jsonb_typeof(p_input->'rawSha256') is distinct from 'string' then raise exception 'Invalid file fields' using errcode='22023';end if;
 fid:=public.pro_bid_uuid_value(p_input->'fileId');
 l:=public.pro_bid_portal_session_link(p_session_hash);
 if l.id is null then raise exception 'Forbidden' using errcode='42501';end if;
 select * into r from public.pro_bid_packages where owner_id=l.owner_id and id=l.package_id;
 if not found then raise exception 'The bid is closed' using errcode='22023',hint='pro_bid_portal_closed';end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-bid-work:'||l.owner_id::text||':'||r.work_id,0));
 select * into l from public.pro_bid_portal_links where owner_id=l.owner_id and id=l.id for update;
 if not found or l.session_hash is distinct from public.pro_bid_portal_hash(p_session_hash) or l.revoked_at is not null or l.expires_at<=now() then raise exception 'Forbidden' using errcode='42501';end if;
 select * into f from public.pro_bid_portal_files where id=fid;
 if found then
  -- Same request retried (lost reply): same link and same bytes return the same reservation.
  if f.owner_id<>l.owner_id or f.link_id<>l.id or f.sha256<>p_input->>'sha256' or f.raw_sha256<>p_input->>'rawSha256' or f.name<>p_input->>'name' or f.mime_type<>p_input->>'mimeType' or f.size_bytes<>(p_input->>'sizeBytes')::integer then
   raise exception 'File identity reused' using errcode='22023';end if;
  return jsonb_build_object('file',public.pro_bid_portal_file_json(f)||jsonb_build_object('ready',f.ready),'objectPath',f.object_path);
 end if;
 select * into r from public.pro_bid_packages where owner_id=l.owner_id and id=l.package_id;
 if r.status<>'open' or r.due_date<today then raise exception 'The bid is closed' using errcode='22023',hint='pro_bid_portal_closed';end if;
 if (select count(*) from public.pro_bid_portal_files where owner_id=l.owner_id and package_id=l.package_id and supplier_id=l.supplier_id and removed_at is null)>=10 then raise exception 'Attachment limit' using errcode='CR429',hint='pro_bid_portal_file_limit';end if;
 if (select count(*) from public.pro_bid_portal_files where owner_id=l.owner_id and link_id=l.id)>=50 then raise exception 'Attachment limit for this link' using errcode='CR429',hint='pro_bid_portal_file_limit';end if;
 ext:=case p_input->>'mimeType' when 'application/pdf' then '.pdf' when 'image/jpeg' then '.jpg' end;
 if ext is null then raise exception 'Invalid file type' using errcode='22023';end if;
 insert into public.pro_bid_portal_files(id,owner_id,package_id,supplier_id,link_id,source_name,name,mime_type,raw_sha256,sha256,size_bytes,object_path)
 values(fid,l.owner_id,l.package_id,l.supplier_id,l.id,p_input->>'sourceName',p_input->>'name',p_input->>'mimeType',p_input->>'rawSha256',p_input->>'sha256',(p_input->>'sizeBytes')::integer,l.owner_id::text||'/'||fid::text||ext) returning * into f;
 return jsonb_build_object('file',public.pro_bid_portal_file_json(f)||jsonb_build_object('ready',f.ready),'objectPath',f.object_path);
end $$;
-- Vendor: the stored bytes were verified by the route; mark the reservation ready (idempotent).
create or replace function public.pro_bid_portal_file_ready(p_session_hash text,p_file uuid,p_sha256 text) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare l public.pro_bid_portal_links;f public.pro_bid_portal_files;
begin
 l:=public.pro_bid_portal_session_link(p_session_hash);
 if l.id is null then raise exception 'Forbidden' using errcode='42501';end if;
 select * into f from public.pro_bid_portal_files where id=p_file and owner_id=l.owner_id and link_id=l.id for update;
 if not found or f.sha256 is distinct from p_sha256 then raise exception 'Invalid file' using errcode='22023';end if;
 if not f.ready then update public.pro_bid_portal_files set ready=true,ready_at=now() where id=f.id returning * into f;end if;
 return jsonb_build_object('file',public.pro_bid_portal_file_json(f));
end $$;
-- Vendor: remove one of its own files while the bid is open.
create or replace function public.pro_bid_portal_file_remove(p_session_hash text,p_file uuid) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare l public.pro_bid_portal_links;r public.pro_bid_packages;f public.pro_bid_portal_files;today date:=public.pro_bid_today();
begin
 l:=public.pro_bid_portal_session_link(p_session_hash);
 if l.id is null then raise exception 'Forbidden' using errcode='42501';end if;
 select * into r from public.pro_bid_packages where owner_id=l.owner_id and id=l.package_id;
 if not found then raise exception 'The bid is closed' using errcode='22023',hint='pro_bid_portal_closed';end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-bid-work:'||l.owner_id::text||':'||r.work_id,0));
 select * into f from public.pro_bid_portal_files where id=p_file and owner_id=l.owner_id and package_id=l.package_id and supplier_id=l.supplier_id and ready for update;
 if not found then raise exception 'Invalid file' using errcode='22023';end if;
 if f.removed_at is not null then return jsonb_build_object('removed',true,'replayed',true);end if;
 select * into r from public.pro_bid_packages where owner_id=l.owner_id and id=l.package_id;
 if r.status<>'open' or r.due_date<today then raise exception 'The bid is closed' using errcode='22023',hint='pro_bid_portal_closed';end if;
 update public.pro_bid_portal_files set removed_at=now() where id=f.id;
 return jsonb_build_object('removed',true);
end $$;
-- Vendor download: only files of its own invitation (any of its links), ready and not removed.
create or replace function public.pro_bid_portal_file_vendor_download(p_session_hash text,p_file uuid) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare l public.pro_bid_portal_links;f public.pro_bid_portal_files;
begin
 l:=public.pro_bid_portal_session_link(p_session_hash);
 if l.id is null then return null;end if;
 select * into f from public.pro_bid_portal_files where id=p_file and owner_id=l.owner_id and package_id=l.package_id and supplier_id=l.supplier_id and ready and removed_at is null;
 if not found then return null;end if;
 return public.pro_bid_portal_file_download_json(f);
end $$;
-- Owner download: only files of the owner's own bids.
create or replace function public.pro_bid_portal_file_owner_download(p_actor uuid,p_file uuid) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare f public.pro_bid_portal_files;
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 select * into f from public.pro_bid_portal_files where id=p_file and owner_id=p_actor and ready and removed_at is null;
 if not found then return null;end if;
 return public.pro_bid_portal_file_download_json(f);
end $$;
-- Owner: attachments of every vendor of one package (comparison view).
create or replace function public.pro_bid_portal_files_owner_read(p_actor uuid,p_query jsonb) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare keys text[];pid uuid;r public.pro_bid_packages;
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if jsonb_typeof(p_query) is distinct from 'object' then raise exception 'Invalid query' using errcode='22023';end if;
 select array_agg(key order by key) into keys from jsonb_object_keys(p_query) key;
 if keys is distinct from array['id','workId'] or jsonb_typeof(p_query->'workId') is distinct from 'string' or length(p_query->>'workId') not between 1 and 160 then raise exception 'Invalid query' using errcode='22023';end if;
 pid:=public.pro_bid_uuid_value(p_query->'id');
 select * into r from public.pro_bid_packages where owner_id=p_actor and work_id=p_query->>'workId' and id=pid;
 if not found then return null;end if;
 return jsonb_build_object('packageId',r.id,'files',coalesce((select jsonb_agg(public.pro_bid_portal_file_json(f)||jsonb_build_object('supplierId',f.supplier_id) order by f.created_at,f.id)
  from public.pro_bid_portal_files f where f.owner_id=p_actor and f.package_id=r.id and f.ready and f.removed_at is null),'[]'::jsonb));
end $$;
-- Vendor: its own attachments and the award notice of its invitation.
create or replace function public.pro_bid_portal_vendor_extras(p_session_hash text) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare l public.pro_bid_portal_links;r public.pro_bid_packages;outcome jsonb:=null;won integer;total_lines integer;won_cents bigint;today date:=public.pro_bid_today();
begin
 l:=public.pro_bid_portal_session_link(p_session_hash);
 if l.id is null then return null;end if;
 select * into r from public.pro_bid_packages where owner_id=l.owner_id and id=l.package_id;
 if not found then return null;end if;
 if r.status='awarded' then
  select count(*)::integer into total_lines from public.pro_bid_lines x where x.owner_id=r.owner_id and x.package_id=r.id;
  select count(*)::integer,coalesce(sum(round(x.quantity*a.unit_cents)),0)::bigint into won,won_cents from public.pro_bid_awards a join public.pro_bid_lines x on x.owner_id=a.owner_id and x.id=a.line_id
   where a.owner_id=r.owner_id and a.package_id=r.id and a.supplier_id=l.supplier_id;
  outcome:=jsonb_build_object('status',case when won=0 then 'not_selected' when won>=total_lines then 'won' else 'partial' end,'decidedAt',r.awarded_at,'lineCount',won,'totalLineCount',total_lines,'wonCents',case when won>0 then won_cents end,
   'lines',coalesce((select jsonb_agg(jsonb_build_object('lineId',x.id,'position',x.position,'description',x.description,'totalCents',round(x.quantity*a.unit_cents)::bigint) order by x.position)
    from public.pro_bid_awards a join public.pro_bid_lines x on x.owner_id=a.owner_id and x.id=a.line_id where a.owner_id=r.owner_id and a.package_id=r.id and a.supplier_id=l.supplier_id),'[]'::jsonb));
 elsif r.status='cancelled' then
  outcome:=jsonb_build_object('status','cancelled','decidedAt',r.cancelled_at,'lineCount',0,'totalLineCount',0,'wonCents',null,'lines','[]'::jsonb);
 end if;
 return jsonb_build_object('canAttach',r.status='open' and r.due_date>=today,
  'files',coalesce((select jsonb_agg(public.pro_bid_portal_file_json(f) order by f.created_at,f.id) from public.pro_bid_portal_files f
   where f.owner_id=l.owner_id and f.package_id=l.package_id and f.supplier_id=l.supplier_id and f.ready and f.removed_at is null),'[]'::jsonb),
  -- Key named «outcome» (not «award»): before a decision the vendor view carries no award wording.
  'outcome',outcome);
end $$;
-- uninvite keeps the vendor's portal attachments (same hint as portal offers). Cascades from a
-- removed account or package (trigger depth > 1) are not blocked.
create or replace function public.pro_bid_portal_file_invitation_guard() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
begin
 if pg_trigger_depth()=1 and exists(select 1 from public.pro_bid_portal_files where owner_id=old.owner_id and package_id=old.package_id and supplier_id=old.supplier_id and ready and removed_at is null) then
  raise exception 'The vendor sent attachments from the portal' using errcode='22023',hint='pro_bid_portal_submissions';
 end if;
 return old;
end $$;
drop trigger if exists pro_bid_portal_file_invitation_guard on public.pro_bid_invitations;
create trigger pro_bid_portal_file_invitation_guard before delete on public.pro_bid_invitations for each row execute function public.pro_bid_portal_file_invitation_guard();
-- Identity and bytes never change; only ready and removal move forward.
create or replace function public.pro_bid_portal_file_guard() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
begin
 if (new.id,new.owner_id,new.package_id,new.supplier_id,new.link_id,new.source_name,new.name,new.mime_type,new.raw_sha256,new.sha256,new.size_bytes,new.object_path,new.created_at)
  is distinct from (old.id,old.owner_id,old.package_id,old.supplier_id,old.link_id,old.source_name,old.name,old.mime_type,old.raw_sha256,old.sha256,old.size_bytes,old.object_path,old.created_at)
  or old.ready and (not new.ready or new.ready_at is distinct from old.ready_at) or old.removed_at is not null and new.removed_at is distinct from old.removed_at then
  raise exception 'Portal files only move forward' using errcode='23514';
 end if;
 return new;
end $$;
drop trigger if exists pro_bid_portal_file_guard on public.pro_bid_portal_files;
create trigger pro_bid_portal_file_guard before update on public.pro_bid_portal_files for each row execute function public.pro_bid_portal_file_guard();

alter table public.pro_bid_portal_files enable row level security;
revoke all on public.pro_bid_portal_files from public,anon,authenticated;
grant select,insert,update,delete on public.pro_bid_portal_files to service_role;
do $$declare f record;begin
 for f in select p.oid::regprocedure signature,p.proname from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'
  and p.proname in('pro_bid_portal_session_link','pro_bid_portal_file_json','pro_bid_portal_file_download_json','pro_bid_portal_file_reserve','pro_bid_portal_file_ready','pro_bid_portal_file_remove','pro_bid_portal_file_vendor_download','pro_bid_portal_file_owner_download','pro_bid_portal_files_owner_read','pro_bid_portal_vendor_extras','pro_bid_portal_file_invitation_guard','pro_bid_portal_file_guard') loop
  execute format('revoke all on function %s from public,anon,authenticated',f.signature);
  if f.proname not in('pro_bid_portal_file_invitation_guard','pro_bid_portal_file_guard') then execute format('grant execute on function %s to service_role',f.signature);end if;
 end loop;
 if to_regclass('storage.buckets') is not null then
  insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('pro-bid-portal-files','pro-bid-portal-files',false,20971520,array['image/jpeg','application/pdf']) on conflict(id) do update set file_size_limit=excluded.file_size_limit;
  if not exists(select 1 from storage.buckets where id='pro-bid-portal-files' and not public and file_size_limit=20971520 and cardinality(allowed_mime_types)=2 and allowed_mime_types @> array['image/jpeg','application/pdf']) then raise exception 'Bid portal files bucket configuration must match the private contract';end if;
 end if;
 if to_regclass('storage.objects') is not null then
  execute 'drop policy if exists pro_bid_portal_files_no_direct on storage.objects';
  execute 'create policy pro_bid_portal_files_no_direct on storage.objects as restrictive for all to anon,authenticated using (bucket_id <> ''pro-bid-portal-files'') with check (bucket_id <> ''pro-bid-portal-files'')';
 end if;
end $$;
notify pgrst,'reload schema';
commit;

-- ===== work-changes-invite-local.sql =====
-- LOCAL PRO ONLY. Round 4B (2026-11-13): extras/changes for a customer linked by project
-- invitation. work-changes-local.sql authorized the customer only through pro_work."bookingClientId"
-- (a booked appointment). A job linked with work-client-invitations-local.sql has instead one
-- confirmed pro_appointment_requests row with origin='project_invite' and no bookingClientId, so
-- the customer got 404. pro_work_change_client() resolves the job's customer account: the booking
-- customer first, otherwise the confirmed invitation link (enabled account). Supersedes
-- pro_work_changes_page and pro_work_changes_mutate with the same signatures, keys and rules;
-- the only differences are that customer resolution and that a change proposed while no account
-- was linked (client_user_id null) is shown to, and answerable by, the account linked now.
-- No table, row or sent message is changed. Reapplicable.
begin;
create or replace function public.pro_work_change_client(p_owner uuid,p_work text) returns uuid
language sql stable security invoker set search_path=public,pg_temp as $$
 select coalesce(
  (select nullif(w."bookingClientId",'')::uuid from public.pro_work w where w.user_id=p_owner and w.id=p_work and w."bookingClientId" ~ '^[0-9a-fA-F-]{36}$'),
  (select r.client_user_id from public.pro_appointment_requests r join public.profiles c on c.id=r.client_user_id
    where r.owner_id=p_owner and r.work_id=p_work and r.origin='project_invite' and r.status in('confirmed','completed') and not coalesce(c.is_disabled,false)
    order by r.updated_at desc,r.id desc limit 1)) $$;
create or replace function public.pro_work_changes_page(p_actor uuid,p_work text default '',p_request uuid default null,p_after bigint default null) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare w pro_work;a jsonb;owner uuid;side text;result jsonb;
begin
 if not exists(select 1 from profiles where id=p_actor and not coalesce(is_disabled,false)) then raise exception 'Forbidden' using errcode='42501';end if;
 if p_after<1 then raise exception 'Invalid cursor' using errcode='22023';end if;
 if p_request is not null then
  -- Round 4B: also the customer linked by project invitation (origin 'project_invite', confirmed).
  select x.* into w from pro_appointment_requests r join pro_work x on x.user_id=r.owner_id and x.id=r.work_id
   where r.id=p_request and p_actor in(r.owner_id,r.client_user_id)
    and (x."bookingClientId"=r.client_user_id::text or r.origin='project_invite' and r.status in('confirmed','completed') and r.client_user_id=public.pro_work_change_client(r.owner_id,x.id));
 else select * into w from pro_work where user_id=p_actor and id=p_work;end if;
 if w.id is null then return null;end if;owner:=w.user_id;side:=case when p_actor=owner then 'provider' else 'client' end;
 a:=pro_work_account(owner,w.id);
 with page as(select * from pro_work_changes where owner_id=owner and work_id=w.id and (side='provider' or client_user_id=p_actor or client_user_id is null and p_actor=public.pro_work_change_client(owner,w.id)) and (p_after is null or position<p_after) order by position desc limit 21)
 select jsonb_build_object('side',side,'workId',w.id,'service',w.service,'clientLinked',public.pro_work_change_client(owner,w.id) is not null,'canPropose',side='provider' and pro_work_changes_enabled(owner) and not w.cancelled and a->>'agreedCents' is not null,
 'account',jsonb_build_object('agreedCents',a->'agreedCents','paidCents',a->'paidCents','balanceCents',a->'balanceCents'),
 'items',coalesce((select jsonb_agg(jsonb_build_object('id',id,'position',position,'reason',reason,'lines',lines,'baseCents',base_cents,'deltaCents',delta_cents,'totalCents',total_cents,'status',status,'stale',status='proposed' and base_position is distinct from (select coalesce(max(e.position),0) from pro_client_entries e where e.user_id=owner and e.work_id=w.id and e.kind='agreement'),'revision',revision,'recordedBy',recorded_by,'acceptanceNote',acceptance_note,'createdAt',created_at,'updatedAt',updated_at) order by position desc) from(select * from page limit 20)t),'[]'),
 'nextCursor',case when(select count(*) from page)>20 then(select position from page offset 19 limit 1) else null end) into result;
 return result;
end $$;
create or replace function public.pro_work_changes_mutate(p_actor uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare owner uuid;w pro_work;c pro_clients;r pro_work_changes;prior pro_work_change_actions;act text:=p_input->>'action';rid uuid:=(p_input->>'id')::uuid;aid uuid:=(p_input->>'actionId')::uuid;a jsonb;delta bigint:=0;v bigint;entry jsonb;amount numeric;latest bigint;result jsonb;is_owner boolean;
begin
 if not exists(select 1 from profiles where id=p_actor and not coalesce(is_disabled,false)) then raise exception 'Forbidden' using errcode='42501';end if;
 if act='propose' then owner:=p_actor;else select owner_id into owner from pro_work_changes where id=rid and (p_actor in(owner_id,client_user_id) or client_user_id is null and p_actor=public.pro_work_change_client(owner_id,work_id));end if;
 if owner is null or rid is null or aid is null or act not in('propose','accept','decline','withdraw','record_acceptance') then raise exception 'Forbidden' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended(owner::text,0));
 select * into prior from pro_work_change_actions where owner_id=owner and actor_id=p_actor and id=aid;
 if found then if prior.input is distinct from p_input then raise exception 'Request changed' using errcode='22023';end if;return prior.result;end if;
 is_owner:=p_actor=owner;
 if act not in('decline','withdraw') and not pro_work_changes_enabled(owner) then raise exception 'Pro required' using errcode='42501';end if;
 if act='propose' then select * into w from pro_work where user_id=owner and id=p_input->>'workId' for update;
 else select * into r from pro_work_changes where owner_id=owner and id=rid for update;select * into w from pro_work where user_id=owner and id=r.work_id for update;
  if r.revision<>(p_input->>'revision')::integer or r.status<>'proposed' then raise exception 'Changed' using errcode='40001';end if;
  if not is_owner and public.pro_work_change_client(owner,w.id) is distinct from p_actor or not is_owner and r.client_user_id is distinct from p_actor and r.client_user_id is not null then raise exception 'Forbidden' using errcode='42501';end if;
 end if;
 if w.id is null then raise exception 'Unavailable work' using errcode='42501';end if;
 select * into c from pro_clients where user_id=owner and id=w."clientId";
 a:=pro_work_account(owner,w.id);
 select coalesce(max(position),0) into latest from pro_client_entries where user_id=owner and work_id=w.id and kind='agreement';
 if act='propose' then
  if not is_owner or w.cancelled or c.archived or a->>'agreedCents' is null then raise exception 'Set an active agreement first' using errcode='22023';end if;
  if (a->>'agreedCents')::bigint<>(p_input->>'baseCents')::bigint then raise exception 'Agreement changed' using errcode='40001';end if;
  if jsonb_typeof(p_input->'lines') is distinct from 'array' or jsonb_array_length(p_input->'lines') not between 1 and 20 or length(btrim(p_input->>'reason')) not between 1 and 500 then raise exception 'Invalid change' using errcode='22023';end if;
  if (select count(*) from pro_work_changes where owner_id=owner and work_id=w.id)>=500 then raise exception 'History limit' using errcode='54000';end if;
  for entry in select value from jsonb_array_elements(p_input->'lines') loop
   amount:=(entry->>'amountCents')::numeric;
   if jsonb_typeof(entry->'description') is distinct from 'string' or length(btrim(entry->>'description')) not between 1 and 160 or amount is null or amount<>round(amount) or amount=0 or abs(amount)>10000000000 then raise exception 'Invalid line' using errcode='22023';end if;
   delta:=delta+amount::bigint;
  end loop;
  amount:=(a->>'agreedCents')::bigint+delta;
  if amount<0 or amount>10000000000 or amount<(a->>'paidCents')::bigint then raise exception 'Invalid total or below received payments' using errcode='22023';end if;
  insert into pro_work_changes(owner_id,id,work_id,client_user_id,reason,lines,base_cents,base_position,delta_cents,total_cents)
  values(owner,rid,w.id,public.pro_work_change_client(owner,w.id),btrim(p_input->>'reason'),p_input->'lines',(a->>'agreedCents')::bigint,latest,delta,amount::bigint) returning * into r;
 else
  if act='withdraw' and not is_owner or act in('accept','decline') and is_owner or act='record_acceptance' and not is_owner then raise exception 'Forbidden' using errcode='42501';end if;
  if act in('accept','record_acceptance') then
   if w.cancelled or c.archived or latest<>r.base_position or (a->>'agreedCents')::bigint is distinct from r.base_cents or r.total_cents<(a->>'paidCents')::bigint then raise exception 'Agreement or balance changed' using errcode='40001';end if;
   if act='record_acceptance' and length(btrim(p_input->>'note')) not between 10 and 500 then raise exception 'Explain external approval' using errcode='22023';end if;
   select revision into v from pro_workspace_core where user_id=owner;
   perform pro_record_client_operation(owner,jsonb_build_object('actionId',aid,'clientId',w."clientId",'workId',w.id,'kind','agreement','amountCents',r.total_cents,'note',left('Cambio aprobado: '||r.reason,160)),v::integer);
  end if;
  update pro_work_changes set status=case when act in('accept','record_acceptance') then 'accepted' when act='decline' then 'declined' else 'withdrawn' end,
   revision=revision+1,recorded_by=case when act in('accept','record_acceptance') then case when is_owner then 'provider' else 'client' end end,
   acceptance_note=case when act='record_acceptance' then btrim(p_input->>'note') else '' end,updated_at=now() where owner_id=owner and id=rid returning * into r;
 end if;
 result:=jsonb_build_object('id',r.id,'revision',r.revision,'status',r.status);
 insert into pro_work_change_actions(owner_id,actor_id,id,input,result) values(owner,p_actor,aid,p_input,result);
 return result;
end $$;
revoke all on function public.pro_work_change_client(uuid,text),public.pro_work_changes_page(uuid,text,uuid,bigint),public.pro_work_changes_mutate(uuid,jsonb) from public,anon,authenticated;
grant execute on function public.pro_work_change_client(uuid,text),public.pro_work_changes_page(uuid,text,uuid,bigint),public.pro_work_changes_mutate(uuid,jsonb) to service_role;
notify pgrst,'reload schema';
commit;

-- ===== lead-shared-quote-stage-local.sql =====
-- LOCAL PRO ONLY. Round 4B (2026-11-13): a manual lead's automatic stage advances to
-- «Cotización enviada» (estimate_sent) once a quote created from that lead
-- (pro_manual_lead_quotes) is shared with the customer (quotes.status sent/accepted/declined,
-- not deleted), the same evidence the request pipeline already uses for public requests.
-- Converting the lead into a job still means «Ganada» (won); with neither it stays «Nueva».
-- A hidden estimate_sent stage follows its reassignment like every other stage. Manual stage
-- mode is unchanged. Supersedes pro_lead_commercial_progress and pro_lead_commercial_sources
-- (lead-commercial-progress-local.sql) with the same signatures and keys; the sources
-- fingerprint also covers the quote evidence so open pages see the change. Read-only.
begin;
create or replace function public.pro_lead_manual_quote_evidence(p_actor uuid,p_lead uuid) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('quoteId',x.id,'status',x.status,'at',x.at) from (
  select q.id::text id,q.status,q.created_at at
  from public.pro_manual_lead_quotes m join public.quotes q on q.id=m.quote_id
  join public.professionals p on p.id=q.professional_id and p.profile_id=p_actor
  where m.owner_id=p_actor and m.lead_kind='manual' and m.lead_id=p_lead and q.deleted_at is null and q.status in('sent','accepted','declined')
  union all
  -- Round 7A: the ONE quote flow is the private estimate; a version created from this lead and
  -- shared with the customer (or already answered) is the same «quote sent» evidence.
  select d.id::text,case s.status when 'accepted' then 'accepted' when 'declined' then 'declined' else 'sent' end,v.created_at
  from public.pro_private_estimates d join public.pro_private_estimate_publications v on v.owner_id=d.owner_id and v.estimate_id=d.id
  join public.pro_private_estimate_publication_states s on s.publication_id=v.id
  where d.owner_id=p_actor and d.source->>'kind'='manual' and d.source->>'id'=p_lead::text and not d.archived
   and s.status in('awaiting_claim','shared','changes_requested','accepted','declined')
 ) x order by x.at desc,x.id desc limit 1 $$;
create or replace function public.pro_lead_commercial_progress(p_actor uuid,p_kind text,p_id uuid)returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$declare l pro_lead_center_records;r jsonb;conv jsonb;automatic_stage text;effective text;current_mode text;begin
 perform pro_lead_origin_owner(p_actor);if p_kind is null or p_kind not in('manual','request')then raise exception'Invalid lead kind'using errcode='22023';end if;
 if p_kind='request'then r:=pro_lead_origin_request(p_actor,p_id);return jsonb_build_object('kind',p_kind,'id',p_id,'mode',r->'state'->'mode','automaticStageId',r->'automaticStageId','effectiveStageId',r->'effectiveStageId','conversion',null);end if;
 select*into l from pro_lead_center_records where owner_id=p_actor and kind='manual'and id=p_id;if not found then raise exception'Opportunity unavailable'using errcode='P0002';end if;
 select jsonb_build_object('actionId',m.action_id,'workId',m.work_id,'at',m.created_at)into conv from pro_manual_lead_works m join pro_work w on w.user_id=m.owner_id and w.id=m.work_id_text and w."clientId"=m.source_client_id and w."bookingClientId"is null where m.owner_id=p_actor and m.lead_kind='manual'and m.lead_id=p_id;
 automatic_stage:=case when conv is not null then'won' when public.pro_lead_manual_quote_evidence(p_actor,p_id) is not null then 'estimate_sent' else'new'end;current_mode:=l.stage_mode;effective:=case when current_mode='manual'then l.stage_id else automatic_stage end;
 select coalesce(reassign_to_id,effective)into effective from pro_request_pipeline_stages where owner_id=p_actor and id=effective;effective:=coalesce(effective,case when current_mode='manual'then l.stage_id else automatic_stage end);
 return jsonb_build_object('kind',p_kind,'id',p_id,'mode',current_mode,'automaticStageId',automatic_stage,'effectiveStageId',effective,'conversion',conv);end $$;
create or replace function public.pro_lead_commercial_sources(p_actor uuid,p_archived boolean,p_query text)returns table(kind text,id uuid,created_at timestamptz,effective_stage text,fingerprint text)language plpgsql stable security invoker set search_path=public,pg_temp as $$begin
 perform pro_lead_origin_owner(p_actor);if p_archived is null or p_query is null or length(p_query)>100 then raise exception'Invalid lead sources query'using errcode='22023';end if;
 return query with base as materialized(select*from pro_lead_center_sources(p_actor,p_archived,p_query)),
 rows as(select b.*,l.stage_mode,m.action_id m_action,m.work_id m_work,m.source_client_id m_client,m.created_at m_at,w.id w_id,
   case when b.kind='manual' and l.stage_mode='automatic' and w.id is null then public.pro_lead_manual_quote_evidence(p_actor,b.id) end quote_evidence
  from base b left join pro_lead_center_records l on l.owner_id=p_actor and l.kind='manual'and l.id=b.id and b.kind='manual'
  left join pro_manual_lead_works m on m.owner_id=p_actor and m.lead_kind='manual'and m.lead_id=l.id
  left join pro_work w on w.user_id=m.owner_id and w.id=m.work_id_text and w."clientId"=m.source_client_id and w."bookingClientId"is null)
 select r.kind,r.id,r.created_at,
  case when r.kind='manual'and r.stage_mode='automatic'then
   case when r.w_id is not null then'won' when r.quote_evidence is not null then coalesce((select s.reassign_to_id from pro_request_pipeline_stages s where s.owner_id=p_actor and s.id='estimate_sent'),'estimate_sent') else'new'end
  else r.effective_stage end,
  md5(r.fingerprint||jsonb_build_array(r.m_action,r.m_work,r.m_client,r.m_at,r.w_id)::text||coalesce(r.quote_evidence::text,''))
 from rows r;end $$;
do $$declare f record;begin for f in select p.oid::regprocedure signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and (p.proname like'pro_lead_commercial_%' or p.proname='pro_lead_manual_quote_evidence') loop execute format('revoke all on function %s from public,anon,authenticated',f.signature);execute format('grant execute on function %s to service_role',f.signature);end loop;end $$;
notify pgrst,'reload schema';
commit;

-- ===== payment-plans-local.sql =====
-- LOCAL PRO ONLY. Round 5 (2026-11-13): «Plan de pagos» — the professional's OWN installment plan for
-- a job. ContrataCR never lends, charges interest or involves a third party: the plan only SCHEDULES the
-- customer balance of the single formula (pro_work_account, client-balance-local.sql), it never changes it.
--
-- * One active plan per job. Every edit is a NEW immutable revision (total, down payment, installments,
--   optional fixed fee and late fee as plain amounts shown as terms). Amounts always sum exactly to the
--   total; the automatic split uses whole colones and the LAST installment absorbs the rounding.
-- * An installment is due on a date, or on a key date (milestone) or when a task is completed.
-- * Applied = payments of the ledger recorded AFTER the plan started (ledger position above the plan's
--   base_position) net of their own voids, capped at [0, total], allocated oldest-first (plan order).
--   Round 6A fix: a void of a payment made BEFORE the plan never touches the plan (it only changes the
--   balance). Derived on every read: a voided post-plan payment is re-allocated automatically.
-- * Status per installment: pending, partial, paid, overdue (due date before today in America/Costa_Rica).
-- * Optional invoice DRAFT for an installment through the same direct-draft writer as Round 4B
--   (pro_invoice_extras_save 'create_direct') with a pro_invoice_billing_items row 'installment'. An
--   installment is billed once while its draft is active; a job is billed either by installments or by
--   quote lines / agreed progress, never both. Archiving the draft releases it; editing or cancelling the
--   plan is refused while one of its installments has an active draft.
-- * Customer view: opt-in section show_payment_plan (OFF by default). The verified linked customer can
--   read it and must ACCEPT the current revision explicitly (timestamp, revision and content hash). A
--   new revision needs a new acceptance. Nothing is e-mailed, notified or charged.
-- Supersedes pro_client_dashboard_settings_json / _mutate (client-view-finances-local.sql) with the same
-- signatures and only the ADDED key showPaymentPlan.
begin;

-- ---------------------------------------------------------------- customer-view section (off by default)
alter table public.pro_client_dashboards add column if not exists show_payment_plan boolean not null default false;

create or replace function public.pro_client_dashboard_settings_json(p_work text,p_row public.pro_client_dashboards) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('workId',p_work,'showUpdates',coalesce(p_row.show_updates,true),'showDailyLogs',coalesce(p_row.show_daily_logs,true),
 'showFiles',coalesce(p_row.show_files,true),'showAllowances',coalesce(p_row.show_allowances,false),'showSelections',coalesce(p_row.show_selections,false),'showSchedule',coalesce(p_row.show_schedule,false),'showPunchlist',coalesce(p_row.show_punchlist,false),'showContracts',coalesce(p_row.show_contracts,false),'showMoodBoards',coalesce(p_row.show_mood_boards,false),'showFinances',coalesce(p_row.show_finances,false),'showPaymentPlan',coalesce(p_row.show_payment_plan,false),'welcomeText',p_row.welcome_text,'revision',coalesce(p_row.revision,0),'updatedAt',p_row.updated_at);
$$;

create or replace function public.pro_client_dashboard_mutate(p_actor uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare wid text;aid uuid;rev integer;keys text[];receipt public.pro_client_dashboard_actions;settings public.pro_client_dashboards;before_json jsonb;after_json jsonb;result jsonb;welcome text;allowances boolean;selections boolean;schedule boolean;punchlist boolean;contracts boolean;moodboards boolean;finances boolean;plan boolean;base_keys text[];
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if jsonb_typeof(p_input) is distinct from 'object' then raise exception 'Invalid dashboard' using errcode='22023';end if;
 select array_agg(key order by key) into keys from jsonb_object_keys(p_input) key;
 -- Every optional section key may be absent so older clients keep working; when absent the stored value is kept.
 select array_agg(k order by k) into base_keys from unnest(keys) k where k not in('showAllowances','showSelections','showSchedule','showContracts','showPunchlist','showMoodBoards','showFinances','showPaymentPlan');
 if base_keys is distinct from array['actionId','revision','showDailyLogs','showFiles','showUpdates','welcomeText','workId']
 or (p_input?'showAllowances' and jsonb_typeof(p_input->'showAllowances') is distinct from 'boolean')
 or (p_input?'showSelections' and jsonb_typeof(p_input->'showSelections') is distinct from 'boolean')
 or (p_input?'showSchedule' and jsonb_typeof(p_input->'showSchedule') is distinct from 'boolean')
 or (p_input?'showPunchlist' and jsonb_typeof(p_input->'showPunchlist') is distinct from 'boolean')
 or (p_input?'showContracts' and jsonb_typeof(p_input->'showContracts') is distinct from 'boolean')
 or (p_input?'showMoodBoards' and jsonb_typeof(p_input->'showMoodBoards') is distinct from 'boolean')
 or (p_input?'showFinances' and jsonb_typeof(p_input->'showFinances') is distinct from 'boolean')
 or (p_input?'showPaymentPlan' and jsonb_typeof(p_input->'showPaymentPlan') is distinct from 'boolean')
 or jsonb_typeof(p_input->'workId') is distinct from 'string' or jsonb_typeof(p_input->'actionId') is distinct from 'string'
 or jsonb_typeof(p_input->'revision') is distinct from 'number' or not coalesce((p_input->>'revision')~'^[0-9]{1,10}$',false)
 or jsonb_typeof(p_input->'showUpdates') is distinct from 'boolean' or jsonb_typeof(p_input->'showDailyLogs') is distinct from 'boolean'
 or jsonb_typeof(p_input->'showFiles') is distinct from 'boolean' or jsonb_typeof(p_input->'welcomeText') not in('string','null') then raise exception 'Invalid dashboard fields' using errcode='22023';end if;
 if (p_input->>'revision')::numeric>2147483646 then raise exception 'Invalid revision' using errcode='22023';end if;
 wid:=p_input->>'workId';aid:=(p_input->>'actionId')::uuid;rev:=(p_input->>'revision')::integer;
 if length(wid) not between 1 and 160 then raise exception 'Invalid dashboard identity' using errcode='22023';end if;
 welcome:=nullif(btrim(coalesce(p_input->>'welcomeText','')),'');
 if welcome is not null and length(welcome)>1000 then raise exception 'Invalid welcome text' using errcode='22023';end if;
 if not exists(select 1 from public.pro_work where user_id=p_actor and id=wid) then raise exception 'Forbidden' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-client-dashboard-action:'||p_actor::text||':'||aid::text,0));
 select * into receipt from public.pro_client_dashboard_actions where actor_id=p_actor and action_id=aid;
 if found then
  if receipt.input is distinct from p_input then raise exception 'Action identity reused with different payload' using errcode='22023';end if;
  return receipt.result;
 end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-client-dashboard:'||p_actor::text||':'||wid,0));
 perform 1 from public.pro_work where user_id=p_actor and id=wid for update;
 if not found then raise exception 'Forbidden' using errcode='42501';end if;
 select * into settings from public.pro_client_dashboards where owner_id=p_actor and work_id=wid for update;
 if not found then
  if rev<>0 then raise exception 'Dashboard changed' using errcode='40001';end if;
  before_json:=null;allowances:=coalesce((p_input->>'showAllowances')::boolean,false);selections:=coalesce((p_input->>'showSelections')::boolean,false);
  schedule:=coalesce((p_input->>'showSchedule')::boolean,false);punchlist:=coalesce((p_input->>'showPunchlist')::boolean,false);contracts:=coalesce((p_input->>'showContracts')::boolean,false);moodboards:=coalesce((p_input->>'showMoodBoards')::boolean,false);finances:=coalesce((p_input->>'showFinances')::boolean,false);plan:=coalesce((p_input->>'showPaymentPlan')::boolean,false);
  insert into public.pro_client_dashboards(owner_id,work_id,show_updates,show_daily_logs,show_files,show_allowances,show_selections,show_schedule,show_contracts,show_punchlist,show_mood_boards,show_finances,show_payment_plan,welcome_text)
   values(p_actor,wid,(p_input->>'showUpdates')::boolean,(p_input->>'showDailyLogs')::boolean,(p_input->>'showFiles')::boolean,allowances,selections,schedule,contracts,punchlist,moodboards,finances,plan,welcome) returning * into settings;
 else
  if rev<>settings.revision then raise exception 'Dashboard changed' using errcode='40001';end if;
  before_json:=public.pro_client_dashboard_settings_json(wid,settings);allowances:=coalesce((p_input->>'showAllowances')::boolean,settings.show_allowances);selections:=coalesce((p_input->>'showSelections')::boolean,settings.show_selections);
  schedule:=coalesce((p_input->>'showSchedule')::boolean,settings.show_schedule);punchlist:=coalesce((p_input->>'showPunchlist')::boolean,settings.show_punchlist);contracts:=coalesce((p_input->>'showContracts')::boolean,settings.show_contracts);moodboards:=coalesce((p_input->>'showMoodBoards')::boolean,settings.show_mood_boards);finances:=coalesce((p_input->>'showFinances')::boolean,settings.show_finances);plan:=coalesce((p_input->>'showPaymentPlan')::boolean,settings.show_payment_plan);
  if settings.show_allowances=allowances and settings.show_selections=selections and settings.show_schedule=schedule and settings.show_punchlist=punchlist and settings.show_contracts=contracts and settings.show_mood_boards=moodboards and settings.show_finances=finances and settings.show_payment_plan=plan and settings.show_updates=(p_input->>'showUpdates')::boolean and settings.show_daily_logs=(p_input->>'showDailyLogs')::boolean
   and settings.show_files=(p_input->>'showFiles')::boolean and settings.welcome_text is not distinct from welcome then raise exception 'No dashboard changes' using errcode='22023';end if;
  update public.pro_client_dashboards set show_updates=(p_input->>'showUpdates')::boolean,show_daily_logs=(p_input->>'showDailyLogs')::boolean,
   show_files=(p_input->>'showFiles')::boolean,show_allowances=allowances,show_selections=selections,show_schedule=schedule,show_contracts=contracts,show_punchlist=punchlist,show_mood_boards=moodboards,show_finances=finances,show_payment_plan=plan,welcome_text=welcome,revision=revision+1,updated_at=now() where owner_id=p_actor and work_id=wid returning * into settings;
 end if;
 after_json:=public.pro_client_dashboard_settings_json(wid,settings);result:=jsonb_build_object('settings',after_json);
 insert into public.pro_client_dashboard_history(owner_id,work_id,action_id,before_settings,after_settings) values(p_actor,wid,aid,before_json,after_json);
 insert into public.pro_client_dashboard_actions(actor_id,action_id,input,result) values(p_actor,aid,p_input,result);
 return result;
end $$;

-- ---------------------------------------------------------------- tables
create table if not exists public.pro_payment_plans(
 owner_id uuid not null references public.profiles(id) on delete cascade,
 work_id text not null check(length(work_id) between 1 and 160),
 id uuid not null,
 status text not null default 'active' check(status in('active','cancelled')),
 revision integer not null default 1 check(revision between 1 and 100000),
 base_paid_cents bigint not null,
 base_position bigint,
 created_at timestamptz not null default now(),updated_at timestamptz not null default now(),
 cancelled_at timestamptz,cancel_reason text check(cancel_reason is null or length(cancel_reason) between 1 and 500),
 primary key(owner_id,id),
 foreign key(owner_id,work_id) references public.pro_work(user_id,id) on delete cascade,
 check((status='cancelled')=(cancelled_at is not null))
);
create unique index if not exists pro_payment_plans_one_active on public.pro_payment_plans(owner_id,work_id) where status='active';
-- Round 6A: ledger position at plan creation (payments above it belong to the plan). Older plans are
-- backfilled with the last ledger position of the owner recorded up to the plan's creation instant.
alter table public.pro_payment_plans add column if not exists base_position bigint;
update public.pro_payment_plans p set base_position=coalesce((select max(e.position) from public.pro_client_entries e where e.user_id=p.owner_id and e.created_at<=p.created_at),0) where p.base_position is null;
-- Payments of a job recorded after a ledger position, net of their own voids (voids of earlier payments are ignored).
create or replace function public.pro_payment_plan_paid_since(p_owner uuid,p_work text,p_position bigint) returns bigint
language sql stable security invoker set search_path=public,pg_temp as $$
 select coalesce(sum(e.amount_cents),0)::bigint-coalesce((select sum(v.amount_cents) from public.pro_client_entries v join public.pro_client_entries o on o.user_id=v.user_id and o.id=v.reversal_id
   where v.user_id=p_owner and v.work_id=p_work and v.kind='payment_void' and o.kind='payment' and o.position>coalesce(p_position,0)),0)::bigint
 from public.pro_client_entries e where e.user_id=p_owner and e.work_id=p_work and e.kind='payment' and e.position>coalesce(p_position,0) $$;
create index if not exists pro_payment_plans_work on public.pro_payment_plans(owner_id,work_id,created_at desc);

create table if not exists public.pro_payment_plan_revisions(
 owner_id uuid not null,plan_id uuid not null,revision integer not null check(revision between 1 and 100000),
 total_cents bigint not null check(total_cents between 100 and 10000000000),
 down_payment_cents bigint not null check(down_payment_cents>=0),
 frequency text not null check(frequency in('weekly','biweekly','monthly','custom')),
 fee_cents bigint not null default 0 check(fee_cents between 0 and 1000000000),
 late_fee_cents bigint not null default 0 check(late_fee_cents between 0 and 1000000000),
 terms text not null default '' check(length(terms)<=1000),
 content_hash text not null check(content_hash~'^[a-f0-9]{64}$'),
 action_id uuid not null,created_at timestamptz not null default now(),
 primary key(owner_id,plan_id,revision),
 foreign key(owner_id,plan_id) references public.pro_payment_plans(owner_id,id) on delete cascade,
 check(down_payment_cents<total_cents)
);
create table if not exists public.pro_payment_plan_items(
 owner_id uuid not null,plan_id uuid not null,revision integer not null,seq integer not null check(seq between 0 and 60),
 kind text not null check(kind in('down','installment')),
 amount_cents bigint not null check(amount_cents between 1 and 10000000000),
 due_date date check(due_date between date '2000-01-01' and date '2100-12-31'),
 milestone_id uuid,task_id uuid,
 primary key(owner_id,plan_id,revision,seq),
 foreign key(owner_id,plan_id,revision) references public.pro_payment_plan_revisions(owner_id,plan_id,revision) on delete cascade,
 check((kind='down')=(seq=0)),
 check(num_nonnulls(due_date,milestone_id,task_id)=1),
 check(kind='installment' or due_date is not null)
);
create table if not exists public.pro_payment_plan_acceptances(
 owner_id uuid not null,plan_id uuid not null,revision integer not null,
 client_user_id uuid not null references public.profiles(id) on delete cascade,request_id uuid not null,
 content_hash text not null check(content_hash~'^[a-f0-9]{64}$'),action_id uuid not null,accepted_at timestamptz not null default now(),
 primary key(owner_id,plan_id,revision),
 foreign key(owner_id,plan_id,revision) references public.pro_payment_plan_revisions(owner_id,plan_id,revision) on delete cascade
);
create table if not exists public.pro_payment_plan_history(
 id bigint generated always as identity primary key,
 owner_id uuid not null,plan_id uuid not null,work_id text not null,actor_id uuid not null,action_id uuid not null,
 action text not null check(action in('create','edit','cancel','accept','invoice')),
 revision integer not null,before_state jsonb,after_state jsonb not null,at timestamptz not null default now(),
 foreign key(owner_id,plan_id) references public.pro_payment_plans(owner_id,id) on delete cascade
);
create index if not exists pro_payment_plan_history_plan on public.pro_payment_plan_history(owner_id,plan_id,id desc);
create table if not exists public.pro_payment_plan_actions(
 actor_id uuid not null references public.profiles(id) on delete cascade,action_id uuid not null,
 input jsonb not null,result jsonb not null,at timestamptz not null default now(),primary key(actor_id,action_id)
);

create or replace function public.pro_payment_plan_immutable() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
begin raise exception 'Payment plan revisions, installments, acceptances, history and receipts are immutable' using errcode='23514';end $$;
drop trigger if exists pro_payment_plan_revision_immutable on public.pro_payment_plan_revisions;
create trigger pro_payment_plan_revision_immutable before update on public.pro_payment_plan_revisions for each row execute function public.pro_payment_plan_immutable();
drop trigger if exists pro_payment_plan_item_immutable on public.pro_payment_plan_items;
create trigger pro_payment_plan_item_immutable before update on public.pro_payment_plan_items for each row execute function public.pro_payment_plan_immutable();
drop trigger if exists pro_payment_plan_acceptance_immutable on public.pro_payment_plan_acceptances;
create trigger pro_payment_plan_acceptance_immutable before update on public.pro_payment_plan_acceptances for each row execute function public.pro_payment_plan_immutable();
drop trigger if exists pro_payment_plan_history_immutable on public.pro_payment_plan_history;
create trigger pro_payment_plan_history_immutable before update on public.pro_payment_plan_history for each row execute function public.pro_payment_plan_immutable();
drop trigger if exists pro_payment_plan_action_immutable on public.pro_payment_plan_actions;
create trigger pro_payment_plan_action_immutable before update on public.pro_payment_plan_actions for each row execute function public.pro_payment_plan_immutable();

-- ---------------------------------------------------------------- invoice drafts: installment source
alter table public.pro_invoice_billing_items drop constraint if exists pro_invoice_billing_items_source_type_check;
alter table public.pro_invoice_billing_items add constraint pro_invoice_billing_items_source_type_check check(source_type in('estimate_line','agreement','time','expense','installment'));
create unique index if not exists pro_invoice_billing_installment_once on public.pro_invoice_billing_items(user_id,source_key) where active and source_type='installment';

-- An installment item can only be (re)activated for the CURRENT revision of an ACTIVE plan; a job is
-- billed by installments OR by quote lines / agreed progress (23505 → the restore or the draft is refused).
create or replace function public.pro_payment_plan_billing_guard() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
declare plan_id uuid;rev integer;
begin
 if not new.active then return new;end if;
 if new.source_type='installment' then
  if new.source_key!~'^[0-9a-f-]{36}:[0-9]{1,6}:[0-9]{1,2}$' then raise exception 'Invalid installment key' using errcode='22023';end if;
  plan_id:=split_part(new.source_key,':',1)::uuid;rev:=split_part(new.source_key,':',2)::integer;
  if not exists(select 1 from public.pro_payment_plans p where p.owner_id=new.user_id and p.id=plan_id and p.work_id=new.work_id and p.status='active' and p.revision=rev) then
   raise exception 'Installment no longer in the current plan' using errcode='23505',hint='pro_billing_already';end if;
  if exists(select 1 from public.pro_invoice_billing_items i where i.user_id=new.user_id and i.work_id=new.work_id and i.active and i.source_type in('estimate_line','agreement')) then
   raise exception 'Job already billed by another method' using errcode='23505',hint='pro_billing_already';end if;
 elsif new.source_type in('estimate_line','agreement') then
  if exists(select 1 from public.pro_invoice_billing_items i where i.user_id=new.user_id and i.work_id=new.work_id and i.active and i.source_type='installment') then
   raise exception 'Job already billed by installments' using errcode='23505',hint='pro_billing_already';end if;
 end if;
 return new;
end $$;
drop trigger if exists pro_payment_plan_billing_guard on public.pro_invoice_billing_items;
create trigger pro_payment_plan_billing_guard before insert or update on public.pro_invoice_billing_items for each row execute function public.pro_payment_plan_billing_guard();

-- ---------------------------------------------------------------- helpers
create or replace function public.pro_payment_plan_today() returns date
language sql stable security invoker set search_path=public,pg_temp as $$ select (clock_timestamp() at time zone 'America/Costa_Rica')::date $$;

create or replace function public.pro_payment_plan_expect(p_input jsonb,p_keys text[]) returns void
language plpgsql immutable security invoker set search_path=public,pg_temp as $$
begin
 if jsonb_typeof(p_input) is distinct from 'object' or not(p_input ?& p_keys) or (p_input-p_keys)<>'{}'::jsonb then raise exception 'Invalid payment plan fields' using errcode='22023';end if;
end $$;
create or replace function public.pro_payment_plan_cents(p_value jsonb,p_min bigint,p_max bigint) returns bigint
language plpgsql immutable security invoker set search_path=public,pg_temp as $$
begin
 if jsonb_typeof(p_value) is distinct from 'number' or (p_value#>>'{}')!~'^[0-9]{1,11}$' or (p_value#>>'{}')::numeric not between p_min and p_max then raise exception 'Invalid amount' using errcode='22023';end if;
 return (p_value#>>'{}')::bigint;
end $$;
create or replace function public.pro_payment_plan_day(p_value jsonb) returns date
language plpgsql immutable security invoker set search_path=public,pg_temp as $$
declare d date;
begin
 if jsonb_typeof(p_value) is distinct from 'string' or (p_value#>>'{}')!~'^\d{4}-\d{2}-\d{2}$' then raise exception 'Invalid date' using errcode='22023';end if;
 begin d:=(p_value#>>'{}')::date;exception when others then raise exception 'Invalid date' using errcode='22008';end;
 if to_char(d,'YYYY-MM-DD')<>(p_value#>>'{}') or d not between date '2000-01-01' and date '2100-12-31' then raise exception 'Invalid date' using errcode='22008';end if;
 return d;
end $$;
create or replace function public.pro_payment_plan_uuid(p_value jsonb) returns uuid
language plpgsql immutable security invoker set search_path=public,pg_temp as $$
begin
 if jsonb_typeof(p_value) is distinct from 'string' or (p_value#>>'{}')!~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then raise exception 'Invalid identifier' using errcode='22023';end if;
 return (p_value#>>'{}')::uuid;
end $$;

-- Automatic split: whole colones, equal installments, the LAST absorbs the rounding.
create or replace function public.pro_payment_plan_split(p_total bigint,p_down bigint,p_count integer) returns bigint[]
language plpgsql immutable security invoker set search_path=public,pg_temp as $$
declare remaining bigint:=p_total-p_down;base bigint;result bigint[]:='{}';
begin
 if p_count is null or p_count not between 1 and 60 or remaining<=0 then raise exception 'Invalid split' using errcode='22023';end if;
 base:=(remaining/p_count/100)*100;
 if base<100 then raise exception 'Installments below one colón' using errcode='22023';end if;
 for k in 1..p_count-1 loop result:=result||base;end loop;
 return result||(remaining-base*(p_count-1));
end $$;
create or replace function public.pro_payment_plan_due(p_first date,p_frequency text,p_index integer) returns date
language sql immutable security invoker set search_path=public,pg_temp as $$
 select case p_frequency when 'weekly' then p_first+7*p_index when 'biweekly' then p_first+14*p_index
  else (p_first+make_interval(months=>p_index))::date end $$;

-- Effective due date of one item: its date, the key date of its milestone, or the CR day its task was completed.
create or replace function public.pro_payment_plan_item_json(p_owner uuid,p_work text,p_item public.pro_payment_plan_items) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('seq',p_item.seq,'kind',p_item.kind,'amountCents',p_item.amount_cents,
  'dueDate',to_char(case when p_item.due_date is not null then p_item.due_date
   when p_item.milestone_id is not null then (select m.milestone_date from public.pro_work_schedule_milestones m where m.owner_id=p_owner and m.work_id=p_work and m.id=p_item.milestone_id and not m.archived)
   else (select (t.updated_at at time zone 'America/Costa_Rica')::date from public.pro_work_tasks t where t.owner_id=p_owner and t.work_id=p_work and t.id=p_item.task_id and t.status='done' and not t.archived) end,'YYYY-MM-DD'),
  'link',case when p_item.milestone_id is not null then jsonb_build_object('kind','milestone','id',p_item.milestone_id,
    'title',(select m.title from public.pro_work_schedule_milestones m where m.owner_id=p_owner and m.work_id=p_work and m.id=p_item.milestone_id),
    'available',exists(select 1 from public.pro_work_schedule_milestones m where m.owner_id=p_owner and m.work_id=p_work and m.id=p_item.milestone_id and not m.archived),'done',null)
   when p_item.task_id is not null then jsonb_build_object('kind','task','id',p_item.task_id,
    'title',(select t.title from public.pro_work_tasks t where t.owner_id=p_owner and t.work_id=p_work and t.id=p_item.task_id),
    'available',exists(select 1 from public.pro_work_tasks t where t.owner_id=p_owner and t.work_id=p_work and t.id=p_item.task_id and not t.archived),
    'done',exists(select 1 from public.pro_work_tasks t where t.owner_id=p_owner and t.work_id=p_work and t.id=p_item.task_id and t.status='done' and not t.archived))
   else null end);
$$;

-- Full derived state of one plan (current revision) for a given CR day. Owner data: callers filter for the customer.
create or replace function public.pro_payment_plan_state(p_owner uuid,p_plan uuid,p_today date) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare p public.pro_payment_plans;r public.pro_payment_plan_revisions;account jsonb;paid bigint;applied bigint;left_over bigint;items jsonb:='[]';i public.pro_payment_plan_items;
 doc jsonb;part bigint;due date;st text;overdue_n integer:=0;overdue_c bigint:=0;upcoming_n integer:=0;upcoming_c bigint:=0;next_due date;draft uuid;acc public.pro_payment_plan_acceptances;last_acc public.pro_payment_plan_acceptances;
begin
 select * into p from public.pro_payment_plans where owner_id=p_owner and id=p_plan;
 if not found then return null;end if;
 select * into r from public.pro_payment_plan_revisions where owner_id=p_owner and plan_id=p.id and revision=p.revision;
 account:=public.pro_work_account(p_owner,p.work_id);
 -- Round 6A: only payments after the plan started, net of their own voids.
 paid:=public.pro_payment_plan_paid_since(p_owner,p.work_id,p.base_position);
 applied:=least(greatest(paid,0),r.total_cents);left_over:=applied;
 for i in select * from public.pro_payment_plan_items where owner_id=p_owner and plan_id=p.id and revision=p.revision order by seq loop
  doc:=public.pro_payment_plan_item_json(p_owner,p.work_id,i);
  part:=least(i.amount_cents,left_over);left_over:=left_over-part;due:=(doc->>'dueDate')::date;
  st:=case when part>=i.amount_cents then 'paid' when due is not null and due<p_today then 'overdue' when part>0 then 'partial' else 'pending' end;
  if p.status='active' and st='overdue' then overdue_n:=overdue_n+1;overdue_c:=overdue_c+i.amount_cents-part;end if;
  if p.status='active' and st in('pending','partial') and due is not null and due between p_today and p_today+7 then upcoming_n:=upcoming_n+1;upcoming_c:=upcoming_c+i.amount_cents-part;end if;
  if p.status='active' and st<>'paid' and due is not null and (next_due is null or due<next_due) then next_due:=due;end if;
  select b.draft_id into draft from public.pro_invoice_billing_items b where b.user_id=p_owner and b.source_type='installment' and b.active and b.source_key=p.id::text||':'||p.revision||':'||i.seq;
  items:=items||(doc||jsonb_build_object('appliedCents',part,'status',st,'invoiceDraftId',draft));
  draft:=null;
 end loop;
 select * into acc from public.pro_payment_plan_acceptances where owner_id=p_owner and plan_id=p.id and revision=p.revision;
 select * into last_acc from public.pro_payment_plan_acceptances where owner_id=p_owner and plan_id=p.id order by revision desc limit 1;
 return jsonb_build_object('planId',p.id,'workId',p.work_id,'status',p.status,'revision',p.revision,'createdAt',p.created_at,'updatedAt',p.updated_at,
  'cancelledAt',p.cancelled_at,'cancelReason',p.cancel_reason,
  'totalCents',r.total_cents,'downPaymentCents',r.down_payment_cents,'frequency',r.frequency,'feeCents',r.fee_cents,'lateFeeCents',r.late_fee_cents,'terms',r.terms,
  'contentHash',r.content_hash,'revisionCreatedAt',r.created_at,
  'appliedCents',applied,'remainingCents',r.total_cents-applied,'customerBalanceCents',account->'customerBalanceCents',
  'items',items,'today',to_char(p_today,'YYYY-MM-DD'),
  'notices',jsonb_build_object('overdueCount',overdue_n,'overdueCents',overdue_c,'upcomingCount',upcoming_n,'upcomingCents',upcoming_c,'nextDue',to_char(next_due,'YYYY-MM-DD')),
  'acceptance',case when acc.plan_id is null then null else jsonb_build_object('revision',acc.revision,'acceptedAt',acc.accepted_at) end,
  'lastAcceptance',case when last_acc.plan_id is null then null else jsonb_build_object('revision',last_acc.revision,'acceptedAt',last_acc.accepted_at) end);
end $$;

-- Canonical content of a revision (what the customer accepts).
create or replace function public.pro_payment_plan_content(p_owner uuid,p_plan uuid,p_revision integer) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('planId',r.plan_id,'revision',r.revision,'totalCents',r.total_cents,'downPaymentCents',r.down_payment_cents,'frequency',r.frequency,
  'feeCents',r.fee_cents,'lateFeeCents',r.late_fee_cents,'terms',r.terms,
  'items',coalesce((select jsonb_agg(jsonb_build_array(i.seq,i.kind,i.amount_cents,i.due_date,i.milestone_id,i.task_id) order by i.seq) from public.pro_payment_plan_items i where i.owner_id=r.owner_id and i.plan_id=r.plan_id and i.revision=r.revision),'[]'::jsonb))
 from public.pro_payment_plan_revisions r where r.owner_id=p_owner and r.plan_id=p_plan and r.revision=p_revision $$;

-- Insert one revision (and its items) from a validated input; raises on any invalid field. The content
-- hash is computed from the same canonical shape as pro_payment_plan_content before the immutable insert.
create or replace function public.pro_payment_plan_write_revision(p_owner uuid,p_work text,p_plan uuid,p_revision integer,p_input jsonb,p_action uuid) returns void
language plpgsql security invoker set search_path=public,pg_temp as $$
declare total bigint;down bigint;fee bigint;late bigint;terms text;sched jsonb;mode text;freq text;n integer;first_due date;down_day date;amounts bigint[];k integer;item jsonb;sum_items bigint:=0;
 last_day date;d date;mid uuid;tid uuid;cnt integer;amount bigint;rows jsonb:='[]';content jsonb;hash text;
begin
 total:=public.pro_payment_plan_cents(p_input->'totalCents',100,10000000000);
 down:=public.pro_payment_plan_cents(p_input->'downPaymentCents',0,10000000000);
 fee:=public.pro_payment_plan_cents(p_input->'feeCents',0,1000000000);late:=public.pro_payment_plan_cents(p_input->'lateFeeCents',0,1000000000);
 if down>=total then raise exception 'Down payment must be below the total' using errcode='22023';end if;
 if jsonb_typeof(p_input->'terms') is distinct from 'string' or length(p_input->>'terms')>1000 then raise exception 'Invalid terms' using errcode='22023';end if;
 terms:=btrim(p_input->>'terms');
 if down>0 then down_day:=public.pro_payment_plan_day(p_input->'downPaymentDate');
 elsif p_input->'downPaymentDate' is distinct from 'null'::jsonb then raise exception 'No down payment date without a down payment' using errcode='22023';end if;
 sched:=p_input->'schedule';
 if jsonb_typeof(sched) is distinct from 'object' or jsonb_typeof(sched->'mode') is distinct from 'string' then raise exception 'Invalid schedule' using errcode='22023';end if;
 mode:=sched->>'mode';
 if mode='auto' then
  perform public.pro_payment_plan_expect(sched,array['mode','frequency','count','firstDue']);
  freq:=sched->>'frequency';if freq is null or freq not in('weekly','biweekly','monthly') then raise exception 'Invalid frequency' using errcode='22023';end if;
  if jsonb_typeof(sched->'count') is distinct from 'number' or (sched->>'count')!~'^[0-9]{1,2}$' then raise exception 'Invalid count' using errcode='22023';end if;
  n:=(sched->>'count')::integer;first_due:=public.pro_payment_plan_day(sched->'firstDue');
  if down_day is not null and first_due<down_day then raise exception 'First installment before the down payment' using errcode='22023';end if;
  amounts:=public.pro_payment_plan_split(total,down,n);
 elsif mode='custom' then
  perform public.pro_payment_plan_expect(sched,array['mode','items']);freq:='custom';
  if jsonb_typeof(sched->'items') is distinct from 'array' or jsonb_array_length(sched->'items') not between 1 and 60 then raise exception 'Invalid installments' using errcode='22023';end if;
  n:=jsonb_array_length(sched->'items');
 else raise exception 'Invalid schedule mode' using errcode='22023';end if;
 if down>0 then rows:=rows||jsonb_build_array(jsonb_build_array(0,'down',down,down_day,null::uuid,null::uuid));sum_items:=down;end if;
 last_day:=down_day;
 for k in 1..n loop
  d:=null;mid:=null;tid:=null;
  if mode='auto' then amount:=amounts[k];d:=public.pro_payment_plan_due(first_due,freq,k-1);
  else
   item:=sched->'items'->(k-1);
   perform public.pro_payment_plan_expect(item,array['amountCents','dueDate','milestoneId','taskId']);
   select count(*) into cnt from jsonb_each(item) e where e.key in('dueDate','milestoneId','taskId') and e.value<>'null'::jsonb;
   if cnt<>1 then raise exception 'Each installment needs exactly one date or one milestone or one task' using errcode='22023';end if;
   amount:=public.pro_payment_plan_cents(item->'amountCents',1,10000000000);
   if item->'dueDate'<>'null'::jsonb then d:=public.pro_payment_plan_day(item->'dueDate');
    -- Dated installments keep the plan order (oldest first).
    if last_day is not null and d<last_day then raise exception 'Installment dates must not go backwards' using errcode='22023';end if;last_day:=d;
   elsif item->'milestoneId'<>'null'::jsonb then mid:=public.pro_payment_plan_uuid(item->'milestoneId');
    if not exists(select 1 from public.pro_work_schedule_milestones m where m.owner_id=p_owner and m.work_id=p_work and m.id=mid and not m.archived) then raise exception 'Milestone not in this job' using errcode='22023';end if;
   else tid:=public.pro_payment_plan_uuid(item->'taskId');
    if not exists(select 1 from public.pro_work_tasks t where t.owner_id=p_owner and t.work_id=p_work and t.id=tid and not t.archived) then raise exception 'Task not in this job' using errcode='22023';end if;
   end if;
  end if;
  rows:=rows||jsonb_build_array(jsonb_build_array(k,'installment',amount,d,mid,tid));sum_items:=sum_items+amount;
 end loop;
 -- Sum invariant: down payment + installments = total, exactly.
 if sum_items<>total then raise exception 'Installments must add up to the total' using errcode='22023',hint='pro_payment_plan_sum';end if;
 content:=jsonb_build_object('planId',p_plan,'revision',p_revision,'totalCents',total,'downPaymentCents',down,'frequency',freq,'feeCents',fee,'lateFeeCents',late,'terms',terms,'items',rows);
 hash:=encode(sha256(convert_to(content::text,'UTF8')),'hex');
 insert into public.pro_payment_plan_revisions(owner_id,plan_id,revision,total_cents,down_payment_cents,frequency,fee_cents,late_fee_cents,terms,content_hash,action_id)
  values(p_owner,p_plan,p_revision,total,down,freq,fee,late,terms,hash,p_action);
 insert into public.pro_payment_plan_items(owner_id,plan_id,revision,seq,kind,amount_cents,due_date,milestone_id,task_id)
  select p_owner,p_plan,p_revision,(r->>0)::integer,r->>1,(r->>2)::bigint,(r->>3)::date,(r->>4)::uuid,(r->>5)::uuid from jsonb_array_elements(rows) r;
 if encode(sha256(convert_to(public.pro_payment_plan_content(p_owner,p_plan,p_revision)::text,'UTF8')),'hex')<>hash then raise exception 'Payment plan content mismatch' using errcode='XX000';end if;
end $$;

-- ---------------------------------------------------------------- owner read
create or replace function public.pro_payment_plan_read(p_actor uuid,p_work text) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare w public.pro_work;c public.pro_clients;today date:=public.pro_payment_plan_today();account jsonb;active_id uuid;state jsonb;link jsonb;visible boolean;
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if p_work is null or length(p_work) not between 1 and 160 then raise exception 'Invalid job' using errcode='22023';end if;
 select * into w from public.pro_work where user_id=p_actor and id=p_work;
 if not found then return null;end if;
 select * into c from public.pro_clients where user_id=p_actor and id=w."clientId";
 account:=public.pro_work_account(p_actor,p_work);
 select id into active_id from public.pro_payment_plans where owner_id=p_actor and work_id=p_work and status='active';
 if active_id is not null then state:=public.pro_payment_plan_state(p_actor,active_id,today);end if;
 link:=public.pro_work_client_link_json(p_actor,p_work);
 select coalesce(d.show_payment_plan,false) into visible from public.pro_client_dashboards d where d.owner_id=p_actor and d.work_id=p_work;
 return jsonb_build_object('workId',w.id,'workTitle',w.service,'clientName',coalesce(c.name,w.client),'cancelled',w.cancelled,'clientArchived',coalesce(c.archived,true),'today',to_char(today,'YYYY-MM-DD'),
  'account',jsonb_build_object('agreedCents',account->'agreedCents','paidCents',account->'paidCents','customerBalanceCents',account->'customerBalanceCents'),
  'plan',state,
  'revisions',case when active_id is null then '[]'::jsonb else coalesce((select jsonb_agg(jsonb_build_object('revision',r.revision,'totalCents',r.total_cents,'createdAt',r.created_at,
    'accepted',exists(select 1 from public.pro_payment_plan_acceptances a where a.owner_id=r.owner_id and a.plan_id=r.plan_id and a.revision=r.revision)) order by r.revision desc)
    from public.pro_payment_plan_revisions r where r.owner_id=p_actor and r.plan_id=active_id),'[]'::jsonb) end,
  'history',coalesce((select jsonb_agg(x.doc order by x.id desc) from (select h.id,jsonb_build_object('action',h.action,'revision',h.revision,'at',h.at,'byClient',h.actor_id<>p_actor) doc
    from public.pro_payment_plan_history h where h.owner_id=p_actor and h.work_id=p_work order by h.id desc limit 30) x),'[]'::jsonb),
  'cancelledPlans',coalesce((select jsonb_agg(jsonb_build_object('planId',p.id,'cancelledAt',p.cancelled_at,'reason',p.cancel_reason,'revision',p.revision,
    'totalCents',(select r.total_cents from public.pro_payment_plan_revisions r where r.owner_id=p.owner_id and r.plan_id=p.id and r.revision=p.revision)) order by p.cancelled_at desc)
    from (select * from public.pro_payment_plans where owner_id=p_actor and work_id=p_work and status='cancelled' order by cancelled_at desc limit 10) p),'[]'::jsonb),
  'options',jsonb_build_object(
    'milestones',coalesce((select jsonb_agg(jsonb_build_object('id',m.id,'title',m.title,'date',to_char(m.milestone_date,'YYYY-MM-DD')) order by m.milestone_date,m.id) from (select * from public.pro_work_schedule_milestones where owner_id=p_actor and work_id=p_work and not archived order by milestone_date,id limit 100) m),'[]'::jsonb),
    'tasks',coalesce((select jsonb_agg(jsonb_build_object('id',t.id,'title',t.title,'status',t.status,'dueDate',to_char(t.due_date,'YYYY-MM-DD')) order by t.due_date nulls last,t.id) from (select * from public.pro_work_tasks where owner_id=p_actor and work_id=p_work and not archived order by due_date nulls last,id limit 100) t),'[]'::jsonb)),
  'linkedClient',case when link is null then null else jsonb_build_object('name',link->'name') end,
  'showInClientView',coalesce(visible,false));
end $$;

-- In-app notices only (overview «Open items»): overdue and next-7-days installments, acceptance pending.
create or replace function public.pro_payment_plan_notices(p_actor uuid,p_work text) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare pid uuid;s jsonb;
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if p_work is null or length(p_work) not between 1 and 160 then raise exception 'Invalid job' using errcode='22023';end if;
 if not exists(select 1 from public.pro_work where user_id=p_actor and id=p_work) then return null;end if;
 select id into pid from public.pro_payment_plans where owner_id=p_actor and work_id=p_work and status='active';
 if pid is null then return jsonb_build_object('active',false,'overdueCount',0,'overdueCents',0,'upcomingCount',0,'upcomingCents',0,'nextDue',null,'awaitingAcceptance',false);end if;
 s:=public.pro_payment_plan_state(p_actor,pid,public.pro_payment_plan_today());
 return jsonb_build_object('active',true)||(s->'notices')||jsonb_build_object('awaitingAcceptance',s->'acceptance'='null'::jsonb and (s->>'remainingCents')::bigint>0);
end $$;

-- ---------------------------------------------------------------- owner writes
create or replace function public.pro_payment_plan_mutate(p_actor uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare act text;aid uuid;receipt public.pro_payment_plan_actions;w public.pro_work;c public.pro_clients;p public.pro_payment_plans;pid uuid;rev integer;before jsonb;after jsonb;result jsonb;
 base bigint;reason text;v_seq integer;it public.pro_payment_plan_items;draft uuid;v_key text;en boolean;label text;n integer;due text;today date:=public.pro_payment_plan_today();
 plan_keys text[]:=array['totalCents','downPaymentCents','downPaymentDate','schedule','feeCents','lateFeeCents','terms'];
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if jsonb_typeof(p_input) is distinct from 'object' or jsonb_typeof(p_input->'action') is distinct from 'string' then raise exception 'Invalid payment plan' using errcode='22023';end if;
 act:=p_input->>'action';
 if act='create' then perform public.pro_payment_plan_expect(p_input,array['action','actionId','workId','planId']||plan_keys);
 elsif act='edit' then perform public.pro_payment_plan_expect(p_input,array['action','actionId','workId','planId','revision']||plan_keys);
 elsif act='cancel' then perform public.pro_payment_plan_expect(p_input,array['action','actionId','workId','planId','revision','reason']);
 elsif act='invoice' then perform public.pro_payment_plan_expect(p_input,array['action','actionId','workId','planId','revision','seq','language']);
 else raise exception 'Invalid payment plan action' using errcode='22023';end if;
 aid:=public.pro_payment_plan_uuid(p_input->'actionId');pid:=public.pro_payment_plan_uuid(p_input->'planId');
 if jsonb_typeof(p_input->'workId') is distinct from 'string' or length(p_input->>'workId') not between 1 and 160 then raise exception 'Invalid job' using errcode='22023';end if;
 if act<>'create' then
  if jsonb_typeof(p_input->'revision') is distinct from 'number' or (p_input->>'revision')!~'^[0-9]{1,6}$' then raise exception 'Invalid revision' using errcode='22023';end if;
  rev:=(p_input->>'revision')::integer;
 end if;
 -- Invoice drafts share the owner lock of every invoice writer (archive/restore included).
 if act='invoice' then perform pg_advisory_xact_lock(hashtextextended(p_actor::text,0));end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-payment-plan-action:'||p_actor::text||':'||aid::text,0));
 select * into receipt from public.pro_payment_plan_actions where actor_id=p_actor and action_id=aid;
 if found then
  if receipt.input is distinct from p_input then raise exception 'Action identity reused with different payload' using errcode='22023';end if;
  return receipt.result;
 end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-payment-plan:'||p_actor::text||':'||(p_input->>'workId'),0));
 select * into w from public.pro_work where user_id=p_actor and id=p_input->>'workId' for update;
 if not found then raise exception 'Forbidden' using errcode='42501';end if;
 select * into c from public.pro_clients where user_id=p_actor and id=w."clientId";
 if act='create' then
  if w.cancelled or coalesce(c.archived,true) then raise exception 'Inactive job' using errcode='22023';end if;
  if exists(select 1 from public.pro_payment_plans where owner_id=p_actor and work_id=w.id and status='active') then raise exception 'Job already has a plan' using errcode='40001';end if;
  if exists(select 1 from public.pro_payment_plans where owner_id=p_actor and id=pid) then raise exception 'Plan identity reused' using errcode='22023';end if;
  base:=coalesce((public.pro_work_account(p_actor,w.id)->>'paidCents')::bigint,0);
  insert into public.pro_payment_plans(owner_id,work_id,id,revision,base_paid_cents,base_position) values(p_actor,w.id,pid,1,base,coalesce((select max(e.position) from public.pro_client_entries e where e.user_id=p_actor),0));
  perform public.pro_payment_plan_write_revision(p_actor,w.id,pid,1,p_input,aid);
  before:=null;after:=public.pro_payment_plan_state(p_actor,pid,today);rev:=1;
 else
  select * into p from public.pro_payment_plans where owner_id=p_actor and id=pid and work_id=w.id for update;
  if not found then raise exception 'Forbidden' using errcode='42501';end if;
  if p.status<>'active' or p.revision<>rev then raise exception 'Plan changed' using errcode='40001';end if;
  before:=public.pro_payment_plan_state(p_actor,pid,today);
  if act in('edit','cancel') then
   if exists(select 1 from public.pro_invoice_billing_items b where b.user_id=p_actor and b.work_id=w.id and b.active and b.source_type='installment' and split_part(b.source_key,':',1)=pid::text) then
    raise exception 'An installment has an active invoice draft' using errcode='22023',hint='pro_payment_plan_invoiced';end if;
  end if;
  if act='edit' then
   if w.cancelled or coalesce(c.archived,true) then raise exception 'Inactive job' using errcode='22023';end if;
   rev:=p.revision+1;
   perform public.pro_payment_plan_write_revision(p_actor,w.id,pid,rev,p_input,aid);
   update public.pro_payment_plans set revision=rev,updated_at=now() where owner_id=p_actor and id=pid;
   -- Same schedule text (content) as before is not an edit.
   if (select content_hash from public.pro_payment_plan_revisions where owner_id=p_actor and plan_id=pid and revision=rev)
     =encode(sha256(convert_to((public.pro_payment_plan_content(p_actor,pid,p.revision)||jsonb_build_object('revision',rev))::text,'UTF8')),'hex') then
    raise exception 'No payment plan changes' using errcode='22023';end if;
  elsif act='cancel' then
   if jsonb_typeof(p_input->'reason') is distinct from 'string' or length(btrim(p_input->>'reason')) not between 1 and 500 then raise exception 'Invalid reason' using errcode='22023';end if;
   reason:=btrim(p_input->>'reason');
   update public.pro_payment_plans set status='cancelled',cancelled_at=now(),cancel_reason=reason,updated_at=now() where owner_id=p_actor and id=pid;
  else -- invoice draft for one installment (same direct-draft writer as Round 4B)
   if w.cancelled or coalesce(c.archived,true) then raise exception 'Inactive job' using errcode='22023';end if;
   if jsonb_typeof(p_input->'seq') is distinct from 'number' or (p_input->>'seq')!~'^[0-9]{1,2}$' then raise exception 'Invalid installment' using errcode='22023';end if;
   if p_input->>'language' is null or p_input->>'language' not in('es','en') then raise exception 'Invalid language' using errcode='22023';end if;
   v_seq:=(p_input->>'seq')::integer;en:=p_input->>'language'='en';
   select * into it from public.pro_payment_plan_items where owner_id=p_actor and plan_id=pid and revision=p.revision and seq=v_seq;
   if not found then raise exception 'Invalid installment' using errcode='22023';end if;
   v_key:=pid::text||':'||p.revision||':'||v_seq;
   if exists(select 1 from public.pro_invoice_billing_items b where b.user_id=p_actor and b.source_type='installment' and b.active and b.source_key=v_key) then raise exception 'Installment already billed' using errcode='23505',hint='pro_billing_already';end if;
   if exists(select 1 from public.pro_invoice_drafts where user_id=p_actor and id=aid) then raise exception 'Request collision' using errcode='40001';end if;
   select count(*) into n from public.pro_payment_plan_items where owner_id=p_actor and plan_id=pid and revision=p.revision and kind='installment';
   due:=(select x->>'dueDate' from jsonb_array_elements(before->'items') x where (x->>'seq')::integer=v_seq);
   label:=left(w.service,120)||' — '||case when it.kind='down' then case when en then 'Down payment' else 'Prima' end
    else case when en then 'Installment ' else 'Cuota ' end||v_seq||case when en then ' of ' else ' de ' end||n end
    ||case when due is not null then case when en then ' · due ' else ' · vence ' end||due else '' end;
   draft:=public.pro_invoice_extras_save(p_actor,jsonb_build_object('action','create_direct','requestId',aid,'clientId',w."clientId",'title',left(label,160),'notes',
    case when en then 'Installment of the payment plan agreed with the customer. Internal draft: nothing is issued, sent or charged.' else 'Cuota del plan de pagos acordado con el cliente. Borrador interno: no se emite, no se envía ni se cobra nada.' end,
    'lines',jsonb_build_array(jsonb_build_object('kind','service','productId',null,'sku','','description',left(label,200),'unit','Sp','cabys','','quantity','1',
     'unitPrice',trim_scale(it.amount_cents::numeric/100)::text,'discountType','percent','discount','0','discountReason','','taxTreatment','pending','taxRate','0'))));
   update public.pro_invoice_drafts set work_id=w.id where user_id=p_actor and id=draft;
   insert into public.pro_invoice_billing_items(user_id,draft_id,item_number,work_id,source_type,source_key,percent_bps,amount_cents,description)
    values(p_actor,draft,1,w.id,'installment',v_key,null,it.amount_cents,left(label,200));
   rev:=p.revision;
  end if;
  after:=public.pro_payment_plan_state(p_actor,pid,today);
 end if;
 insert into public.pro_payment_plan_history(owner_id,plan_id,work_id,actor_id,action_id,action,revision,before_state,after_state) values(p_actor,pid,w.id,p_actor,aid,act,rev,before,after);
 result:=jsonb_build_object('plan',after)||case when act='invoice' then jsonb_build_object('draftId',draft) else '{}'::jsonb end;
 insert into public.pro_payment_plan_actions(actor_id,action_id,input,result) values(p_actor,aid,p_input,result);
 return result;
end $$;

-- ---------------------------------------------------------------- customer (verified linked customer only)
-- Customer copy: amounts, dates, status and terms. Never the base, invoice ids, milestone/task ids or task names.
create or replace function public.pro_payment_plan_client_json(p_state jsonb) returns jsonb
language sql immutable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('planId',p_state->'planId','revision',p_state->'revision','totalCents',p_state->'totalCents','downPaymentCents',p_state->'downPaymentCents',
  'frequency',p_state->'frequency','feeCents',p_state->'feeCents','lateFeeCents',p_state->'lateFeeCents','terms',p_state->'terms','contentHash',p_state->'contentHash',
  'appliedCents',p_state->'appliedCents','remainingCents',p_state->'remainingCents','today',p_state->'today','revisionCreatedAt',p_state->'revisionCreatedAt',
  'items',coalesce((select jsonb_agg(jsonb_build_object('seq',i->'seq','kind',i->'kind','amountCents',i->'amountCents','dueDate',i->'dueDate','appliedCents',i->'appliedCents','status',i->'status',
    'link',case when i->'link'='null'::jsonb then null when i->'link'->>'kind'='milestone' then jsonb_build_object('kind','milestone','title',i->'link'->'title') else jsonb_build_object('kind','task','title',null) end) order by (i->>'seq')::integer)
   from jsonb_array_elements(p_state->'items') i),'[]'::jsonb),
  'acceptance',p_state->'acceptance','canAccept',p_state->'acceptance'='null'::jsonb) $$;

create or replace function public.pro_payment_plan_client_read(p_actor uuid,p_request uuid) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare r public.pro_appointment_requests;visible boolean;pid uuid;w public.pro_work;
begin
 if not exists(select 1 from public.profiles where id=p_actor and not coalesce(is_disabled,false)) then raise exception 'Forbidden' using errcode='42501';end if;
 if p_request is null then raise exception 'Invalid payment plan query' using errcode='22023';end if;
 select * into r from public.pro_appointment_requests where id=p_request and client_user_id=p_actor and work_id is not null;
 if not found then return null;end if;
 select coalesce(d.show_payment_plan,false) into visible from public.pro_client_dashboards d where d.owner_id=r.owner_id and d.work_id=r.work_id;
 if not coalesce(visible,false) or r.status not in('confirmed','completed') then return jsonb_build_object('visible',false);end if;
 select * into w from public.pro_work where user_id=r.owner_id and id=r.work_id;
 if not found then return jsonb_build_object('visible',false);end if;
 select id into pid from public.pro_payment_plans where owner_id=r.owner_id and work_id=r.work_id and status='active';
 return jsonb_build_object('visible',true,'workTitle',w.service,
  'plan',case when pid is null then null else public.pro_payment_plan_client_json(public.pro_payment_plan_state(r.owner_id,pid,public.pro_payment_plan_today())) end);
end $$;

create or replace function public.pro_payment_plan_client_mutate(p_actor uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare aid uuid;receipt public.pro_payment_plan_actions;r public.pro_appointment_requests;visible boolean;p public.pro_payment_plans;rv public.pro_payment_plan_revisions;rev integer;before jsonb;after jsonb;result jsonb;
begin
 if not exists(select 1 from public.profiles where id=p_actor and not coalesce(is_disabled,false)) then raise exception 'Forbidden' using errcode='42501';end if;
 perform public.pro_payment_plan_expect(p_input,array['action','actionId','requestId','planId','revision','contentHash']);
 if p_input->>'action' is distinct from 'accept' then raise exception 'Invalid payment plan answer' using errcode='22023';end if;
 aid:=public.pro_payment_plan_uuid(p_input->'actionId');
 if jsonb_typeof(p_input->'revision') is distinct from 'number' or (p_input->>'revision')!~'^[0-9]{1,6}$' then raise exception 'Invalid revision' using errcode='22023';end if;
 if jsonb_typeof(p_input->'contentHash') is distinct from 'string' or (p_input->>'contentHash')!~'^[a-f0-9]{64}$' then raise exception 'Invalid hash' using errcode='22023';end if;
 rev:=(p_input->>'revision')::integer;
 perform pg_advisory_xact_lock(hashtextextended('pro-payment-plan-action:'||p_actor::text||':'||aid::text,0));
 select * into receipt from public.pro_payment_plan_actions where actor_id=p_actor and action_id=aid;
 if found then
  if receipt.input is distinct from p_input then raise exception 'Action identity reused with different payload' using errcode='22023';end if;
  return receipt.result;
 end if;
 -- Only the customer linked to this job through a confirmed request (appointment or accepted invitation).
 select * into r from public.pro_appointment_requests where id=public.pro_payment_plan_uuid(p_input->'requestId') and client_user_id=p_actor and work_id is not null and status in('confirmed','completed');
 if not found then raise exception 'Forbidden' using errcode='42501';end if;
 select coalesce(d.show_payment_plan,false) into visible from public.pro_client_dashboards d where d.owner_id=r.owner_id and d.work_id=r.work_id;
 if not coalesce(visible,false) then raise exception 'Forbidden' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-payment-plan:'||r.owner_id::text||':'||r.work_id,0));
 select * into p from public.pro_payment_plans where owner_id=r.owner_id and work_id=r.work_id and id=public.pro_payment_plan_uuid(p_input->'planId') for update;
 if not found then raise exception 'Forbidden' using errcode='42501';end if;
 select * into rv from public.pro_payment_plan_revisions where owner_id=p.owner_id and plan_id=p.id and revision=p.revision;
 -- The customer accepts exactly the revision (and content) currently shown.
 if p.status<>'active' or p.revision<>rev or rv.content_hash<>p_input->>'contentHash' then raise exception 'Plan changed' using errcode='40001';end if;
 if exists(select 1 from public.pro_payment_plan_acceptances where owner_id=p.owner_id and plan_id=p.id and revision=p.revision) then raise exception 'Plan already accepted' using errcode='40001';end if;
 before:=public.pro_payment_plan_state(p.owner_id,p.id,public.pro_payment_plan_today());
 insert into public.pro_payment_plan_acceptances(owner_id,plan_id,revision,client_user_id,request_id,content_hash,action_id) values(p.owner_id,p.id,p.revision,p_actor,r.id,rv.content_hash,aid);
 after:=public.pro_payment_plan_state(p.owner_id,p.id,public.pro_payment_plan_today());
 insert into public.pro_payment_plan_history(owner_id,plan_id,work_id,actor_id,action_id,action,revision,before_state,after_state) values(p.owner_id,p.id,p.work_id,p_actor,aid,'accept',p.revision,before,after);
 result:=jsonb_build_object('plan',public.pro_payment_plan_client_json(after));
 insert into public.pro_payment_plan_actions(actor_id,action_id,input,result) values(p_actor,aid,p_input,result);
 return result;
end $$;

-- ---------------------------------------------------------------- RLS and grants (service_role only)
do $$declare n text;begin foreach n in array array['pro_payment_plans','pro_payment_plan_revisions','pro_payment_plan_items','pro_payment_plan_acceptances','pro_payment_plan_history','pro_payment_plan_actions'] loop
 execute format('alter table public.%I enable row level security',n);execute format('revoke all on public.%I from public,anon,authenticated',n);execute format('grant select,insert,update,delete on public.%I to service_role',n);
 end loop;end $$;
do $$
declare f regprocedure;
begin
 for f in select p.oid::regprocedure from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname like 'pro\_payment\_plan\_%' loop
  execute format('revoke all on function %s from public,anon,authenticated',f);
  if f::text not like 'pro_payment_plan_immutable(%' and f::text not like 'pro_payment_plan_billing_guard(%' then execute format('grant execute on function %s to service_role',f);end if;
 end loop;
end $$;
revoke all on function public.pro_client_dashboard_settings_json(text,public.pro_client_dashboards),public.pro_client_dashboard_mutate(uuid,jsonb) from public,anon,authenticated;
grant execute on function public.pro_client_dashboard_settings_json(text,public.pro_client_dashboards),public.pro_client_dashboard_mutate(uuid,jsonb) to service_role;
notify pgrst,'reload schema';
commit;
